// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Temel ekonomi kavramları: arz-talep, piyasa, üretim (orta).
const ozEconomics1Orta = <(String, String, List<String>, String)>[
  ('Selin bir telefon istemektedir ancak hiç parası yoktur. Ekonomik açıdan Selin\'in bu durumu için aşağıdakilerden hangisi söylenebilir?', 'İhtiyacı vardır ancak etkin talebi yoktur.', ['Telefon piyasasında arz fazlası yaratır.', 'Telefonun fiyat esnekliğini sıfıra indirir.', 'Telefon onun için serbest bir maldır.'], 'Talep, satın alma isteğinin satın alma gücüyle desteklenmesidir. Parası olmayan kişinin isteği piyasada talep olarak görünmez.'),
  ('Kıtlık sorunu ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Zengin ülkeler de dâhil tüm toplumlar kıtlıkla karşı karşıyadır.', ['Kıtlık yalnızca yoksul ülkelerin sorunudur.', 'Teknoloji geliştikçe kıtlık bütün toplumlarda tamamen ortadan kalkar.', 'Kıtlık sadece doğal kaynaklar için geçerlidir.'], 'Kaynaklar her toplumda ihtiyaçlara göre sınırlıdır; zaman, emek ve sermaye de kıttır. Bu yüzden kıtlık evrenseldir.'),
  ('Emre cumartesi günü ya saati 200 TL\'den 5 saat garsonluk yapabilir, ya saati 150 TL\'den 6 saat kurye olarak çalışabilir ya da arkadaşlarıyla maça gidebilir. Emre maça giderse fırsat maliyeti kaç TL olur?', '1.000 TL', ['900 TL', '1.900 TL', '750 TL'], 'Garsonluk 5 × 200 = 1.000 TL, kuryelik 6 × 150 = 900 TL getirir. Fırsat maliyeti yalnızca vazgeçilen en iyi seçenek olan 1.000 TL\'dir; seçenekler toplanmaz.'),
  ('Üniversite okumanın fırsat maliyeti hesaplanırken aşağıdakilerden hangisi kesinlikle dikkate alınmalıdır?', 'Okul yerine çalışılsaydı kazanılacak gelir', ['Okurken de yapılacak olan yemek harcamaları', 'Daha önce ödenmiş ve geri alınamayan kurs ücreti', 'Ailenin okul dışındaki tasarrufları'], 'Okumasa da yapılacak harcamalar ve geri alınamayan geçmiş harcamalar seçimi etkilemez. Vazgeçilen iş geliri ise okumanın en önemli fırsat maliyetidir.'),
  ('Aşağıdaki durumların hangisinde bir kişinin film izlemeye gitmesinin fırsat maliyeti en yüksektir?', 'Ertesi gün kritik bir sınavı olan öğrencinin ders çalışmak yerine sinemaya gitmesi', ['İşsiz ve hiçbir planı olmayan birinin boş bir hafta içi akşamı sinemaya gitmesi', 'Emekli birinin tatil gününde sinemaya gitmesi', 'Ödevlerini bitirmiş birinin hafta sonu sinemaya gitmesi'], 'Fırsat maliyeti, vazgeçilen en iyi seçeneğin değerine bağlıdır. Kritik sınav öncesi ders çalışmanın değeri diğer durumlardaki alternatiflerden çok yüksektir.'),
  ('Bir ekonomi üretim imkânları eğrisinin içindeki bir noktada üretim yapıyorsa bu durum neyi gösterir?', 'Kaynakların atıl ya da etkinsiz kullanıldığını', ['Ekonominin mevcut teknolojik sınırını aşarak üretim yaptığını', 'Kaynakların tamamen ve etkin kullanıldığını', 'Dış ticaretin yasaklandığını'], 'Eğrinin içindeki noktalar, işsizlik ya da kaynak israfı nedeniyle olası üretimin altında kalındığını gösterir.'),
  ('Üretim imkânları eğrisinin orijine göre dışbükey değil içbükey (dışa doğru bombeli) olmasının nedeni nedir?', 'Kaynakların her iki malın üretimine eşit uygunlukta olmaması', ['Teknolojinin her yıl sabit hızla gelişmesi', 'Tüketicilerin iki malı eşit derecede sevmesi ve aynı fiyatla alması', 'Ekonomide işsizlik bulunması'], 'Kaynaklar uzmanlaşmış olduğundan bir maldan daha fazla üretmek için giderek daha az uygun kaynaklar aktarılır; bu da artan fırsat maliyeti ve içbükey eğri doğurur.'),
  ('Bir ülke tüm kaynaklarını kullanarak ya 100 ton buğday ya da 50 bilgisayar üretebilmektedir ve üretim imkânları eğrisi doğrusaldır. Bu ülkede 1 bilgisayarın fırsat maliyeti kaç ton buğdaydır?', '2 ton', ['0,5 ton', '50 ton', '100 ton'], 'Doğrusal eğride 50 bilgisayar için 100 ton buğdaydan vazgeçilir; 1 bilgisayarın fırsat maliyeti 100 / 50 = 2 ton buğdaydır.'),
  ('Bir ekonominin üretim imkânları eğrisinin dışında bulunan bir noktaya mevcut kaynaklarla ulaşılması neden mümkün değildir?', 'Bu nokta mevcut kaynak ve teknolojinin üretebileceğinden fazlasını gerektirir.', ['Bu noktada kaynaklar atıl kalmaktadır.', 'Bu noktada fırsat maliyeti sıfırdır.', 'Bu nokta yalnızca tek bir malın üretilmesini gösterir.'], 'Eğrinin dışı ulaşılamaz bölgedir; buraya ancak kaynak artışı, teknolojik gelişme ya da dış ticaretle tüketim yoluyla ulaşılabilir.'),
  ('Bir fırının ekmek yapmak için satın aldığı un hangi mal türüne girer?', 'Ara mal', ['Nihai tüketim malı', 'Kamusal mal', 'Lüks mal'], 'Başka bir malın üretiminde girdi olarak kullanılan mallar ara maldır. Aynı un bir hane tarafından ev için alınırsa nihai mal olur.'),
  ('Aynı mal bazı durumlarda ara mal, bazı durumlarda nihai mal olabilir. Aşağıdakilerden hangisi nihai mal olarak kullanılmaktadır?', 'Bir ailenin kahvaltı için marketten aldığı yumurta', ['Pastanenin kek yapımı için aldığı yumurta', 'Lokantanın menemen yapmak için aldığı yumurta', 'Makarna fabrikasının yumurtalı erişte üretimi için aldığı yumurta'], 'Malın türünü kullanım amacı belirler. Son tüketiciye ulaşıp tüketilen yumurta nihai maldır; üretimde girdi olanlar ara maldır.'),
  ('Hizmetleri mallardan ayıran temel özellik aşağıdakilerden hangisidir?', 'Genellikle üretildikleri anda tüketilmeleri ve stoklanamamaları', ['Hiçbir zaman fiyatlarının olmaması', 'Yalnızca devlet tarafından sunulmaları', 'Mutlaka gelişmiş makineler ve fabrika ortamında üretilmeleri'], 'Saç kesimi ya da ders anlatımı gibi hizmetler soyuttur; üretim ve tüketim çoğunlukla aynı anda gerçekleşir ve depolanamaz.'),
  ('Çay ile şeker gibi birlikte tüketildiğinde fayda sağlayan mallara ne ad verilir?', 'Tamamlayıcı mallar', ['İkame mallar', 'Birbirinden bağımsız mallar', 'Düşük mallar'], 'Birinin tüketimi diğerinin tüketimini gerektiren ya da artıran mallar tamamlayıcıdır. Birbirinin yerine geçebilenler ise ikame maldır.'),
  ('Ekonomide "sermaye" denildiğinde üretim faktörü olarak öncelikle ne kastedilir?', 'Üretimde kullanılan makine, bina ve araç gibi insan yapımı araçlar', ['Kişilerin bankadaki mevduatları', 'Hisse senedi ve tahvil gibi şirket ortaklığı veya borç gösteren kâğıtlar', 'Toprak altındaki maden yatakları'], 'Üretim faktörü olarak sermaye, üretilmiş üretim araçlarıdır (fiziki sermaye). Para ise bu araçları satın almaya yarayan bir araçtır.'),
  ('Bir çiftçinin tarlasını başka birine kiraya verip aldığı bedel hangi faktör gelirine örnektir?', 'Rant', ['Ücret', 'Kâr', 'Faiz'], 'Toprak gibi doğal kaynakların üretime katılmasının karşılığı ranttır.'),
  ('Girişimciyi diğer üretim faktörlerinden ayıran temel özellik hangisidir?', 'Üretimin riskini üstlenip diğer faktörleri bir araya getirmesi', ['Gelirinin önceden yapılan bir sözleşmeyle sabit tutar olarak belirlenmesi', 'Yalnızca bedensel emek harcaması', 'Doğada kendiliğinden bulunması'], 'Girişimci emek, sermaye ve doğal kaynağı örgütler ve belirsizliği üstlenir; geliri olan kâr önceden garanti edilmez ve zarar da olabilir.'),
  ('Kaynakların tahsisine büyük ölçüde fiyatlar, arz ve talep aracılığıyla karar verilen sistem hangisidir?', 'Piyasa ekonomisi', ['Komuta ekonomisi', 'Geleneksel ekonomi', 'Merkezî planlama ekonomisi'], 'Piyasa ekonomisinde üretim ve tüketim kararlarını hane halkları ve firmalar fiyat sinyallerine göre verir.'),
  ('Merkezî planlı (komuta) ekonomide temel ekonomik sorulara kim yanıt verir?', 'Devletin planlama kurumları', ['Serbest piyasada oluşan fiyatlar ve kâr güdüsü', 'Bireysel tüketiciler', 'Gelenek ve görenekler'], 'Komuta ekonomisinde ne, nasıl ve kimin için üretileceğine merkezi otorite plan yoluyla karar verir.'),
  ('Ekonomik kararların büyük ölçüde atalardan kalan alışkanlıklara göre alındığı, kuşaklar boyunca aynı mesleklerin sürdürüldüğü sistem hangisidir?', 'Geleneksel ekonomi', ['Karma ekonomi', 'Piyasa ekonomisi', 'Komuta ekonomisi'], 'Geleneksel ekonomilerde üretim yöntemleri ve paylaşım kuralları gelenekle belirlenir; değişim yavaştır.'),
  ('Piyasa ekonomisinde "kimin için üretilecek?" sorusu temelde neye göre yanıtlanır?', 'Bireylerin gelir ve satın alma gücüne', ['Devletin her aileye eşit olarak dağıttığı karne miktarına', 'Kişilerin yaşına', 'Üretilen malın ağırlığına'], 'Piyasada mallar, fiyatını ödemeye istekli ve gücü yeten kişilere gider; dolayısıyla dağılım gelire bağlıdır.'),
  ('Aşağıdaki ifadelerden hangisi normatif bir ekonomi ifadesidir?', 'Devlet, düşük gelirli ailelere daha fazla destek vermelidir.', ['Fiyat yükselince talep edilen miktar azalır.', 'Geçen yıl buğday üretimi bir önceki yıla göre yaklaşık yüzde on azaldı.', 'Vergi artışı sigara tüketimini düşürür.'], 'Normatif ifadeler "olması gereken"i söyler ve değer yargısı içerir; pozitif ifadeler ise doğruluğu verilerle sınanabilecek "olan"ı anlatır.'),
  ('"Asgari ücretin artırılması genç işçilerin bir kısmının iş bulmasını zorlaştırır." ifadesi için aşağıdakilerden hangisi doğrudur?', 'Verilerle sınanabilecek pozitif bir ifadedir.', ['Değer yargısı içeren normatif bir ifadedir.', 'Makroekonomiyle ilgisi olmayan bir tanımdır.', 'Hiçbir koşulda sınanamayacak ve doğrulanamayacak bir varsayımdır.'], 'İfade doğru ya da yanlış olabilir ama bir neden-sonuç iddiasıdır ve verilerle sınanabilir; bu nedenle pozitiftir.'),
  ('Bir malın fiyatı düştüğünde tüketicilerin, pahalılaşmış olan benzer mallar yerine bu malı daha çok almasına ne ad verilir?', 'İkame etkisi', ['Gelir etkisi', 'Çarpan etkisi', 'Veblen etkisi'], 'Göreli olarak ucuzlayan mal diğerlerinin yerine ikame edilir; bu, talep kanununu açıklayan iki etkiden biridir.'),
  ('Bir malın fiyatı düştüğünde tüketicinin aynı parayla daha fazla mal alabilmesi sonucu talep edilen miktarın artması hangi etkiyle açıklanır?', 'Gelir etkisi', ['İkame etkisi', 'Gösteriş etkisi', 'Dışsallık etkisi'], 'Fiyat düşüşü tüketicinin reel gelirini (satın alma gücünü) artırır; bu da normal mallarda talep edilen miktarı yükseltir.'),
  ('Bir bisküvinin talep fonksiyonu Qd = 120 − 4P biçimindedir. Fiyat 15 TL olduğunda talep edilen miktar kaçtır?', '60', ['105', '45', '75'], 'Qd = 120 − 4 × 15 = 120 − 60 = 60 birimdir.'),
  ('Piyasa talep eğrisi nasıl elde edilir?', 'Her fiyatta bireysel talep miktarlarının toplanmasıyla', ['Bireysel talep eğrilerinin ortalamasının alınıp kişi sayısına bölünmesiyle', 'Arz eğrisinin tersinin alınmasıyla', 'En zengin tüketicinin talebinin esas alınmasıyla'], 'Piyasa talebi, her fiyat düzeyinde tüm tüketicilerin talep ettiği miktarların yatay toplamıdır.'),
  ('Yazıcı fiyatları büyük ölçüde düşerse yazıcı kartuşu piyasasında ne olması beklenir?', 'Kartuş talebi artar.', ['Kartuş talebi azalır.', 'Kartuş arzı azalır.', 'Kartuş fiyatı sıfıra iner.'], 'Yazıcı ve kartuş tamamlayıcı mallardır. Yazıcı ucuzlayıp daha çok satılınca kartuş talebi de artar.'),
  ('Aşağıdakilerden hangisi bir malın talebini (talep eğrisinin konumunu) değiştiren etkenlerden biri değildir?', 'Malın kendi fiyatı', ['Tüketicilerin geliri', 'İkame malların fiyatı', 'Tüketici zevk ve tercihleri'], 'Malın kendi fiyatındaki değişme eğri boyunca harekete yol açar; diğer etkenler ise eğrinin tamamını kaydırır.'),
  ('Tüketiciler gelecek ay benzin fiyatlarının yükseleceğini bekliyorsa bu ay benzin piyasasında ne olması beklenir?', 'Bugünkü benzin talebi artar.', ['Bugünkü benzin talebi azalır.', 'Benzinin arzı hemen artar.', 'Benzin talebinin fiyat esnekliği sıfır olur.'], 'Fiyat artışı beklentisi tüketicileri alımlarını öne çekmeye yöneltir; bu da bugünkü talep eğrisini sağa kaydırır.'),
  ('Bir kasabaya büyük bir üniversite açılarak nüfus hızla arttığında kiralık daire piyasasında ne olur?', 'Kiralık daire talebi artar.', ['Kiralık daire talebi azalır.', 'Kiralık daire arzı azalır.', 'Kira fiyatları kesin olarak düşer.'], 'Alıcı sayısındaki artış piyasa talebini artırır ve talep eğrisini sağa kaydırır.'),
  ('Kış aylarının yaklaşmasıyla mont piyasasında aşağıdakilerden hangisinin gerçekleşmesi beklenir?', 'Mont talebinin artması', ['Mont talebinin azalması', 'Mont arzının azalması', 'Mont fiyatlarının sıfıra inmesi'], 'Mevsim, tercihleri etkileyen bir etkendir; soğuk havalar mont talebini artırarak eğriyi sağa kaydırır.'),
  ('Gelir arttıkça talebi azalan mallar nasıl adlandırılır?', 'Düşük (inferior) mal', ['Lüks mal', 'Zorunlu mal', 'Tamamlayıcı mal'], 'Düşük mallarda tüketiciler gelirleri artınca daha kaliteli seçeneklere yönelir; gelir esnekliği negatiftir.'),
  ('Geliri artan bir öğrencinin hazır noodle yerine restoranda yemek yemeye başlaması, noodle için ne gösterir?', 'Noodle bu öğrenci için düşük maldır.', ['Noodle bu öğrenci için lüks maldır.', 'Noodle ile restoran yemeği tamamlayıcıdır.', 'Noodle bir Giffen malıdır.'], 'Gelir artınca tüketimi azalan mal düşük maldır. Giffen olması için fiyatı artınca talebinin artması gerekirdi.'),
  ('Giffen malı ile Veblen malı arasındaki temel fark hangisidir?', 'Giffen malı düşük maldır, Veblen malı ise statü için tüketilen pahalı bir maldır.', ['Giffen malının fiyatı artınca talebi azalır, Veblen malınınki artar.', 'Veblen malı yalnızca hizmetlerden oluşur.', 'İkisi arasında hiçbir fark yoktur; aynı kavramın farklı ülkelerde kullanılan adlarıdır.'], 'Her ikisinde de fiyat artınca talep edilen miktar artabilir, ancak nedenleri farklıdır: Giffen\'de güçlü gelir etkisi, Veblen\'de gösteriş isteği.'),
  ('Aşağıdaki gelişmelerden hangisi dondurma piyasasında talep eğrisinin kaymasına değil, eğri üzerinde harekete yol açar?', 'Dondurmanın kendi fiyatının düşmesi', ['Havaların beklenmedik biçimde ısınması', 'Tüketicilerin gelirlerinin artması', 'Dondurmanın sağlığa yararlı olduğunun açıklanması'], 'Malın kendi fiyatı dışındaki etkenler eğriyi kaydırır; kendi fiyatı ise eğri üzerinde hareket yaratır.'),
  ('Bir gazete "Otomobil fiyatları düştü, otomobil talebi arttı." diye yazmıştır. Ekonomi diliyle bu cümle nasıl düzeltilmelidir?', 'Otomobil fiyatları düştü, talep edilen otomobil miktarı arttı.', ['Otomobil fiyatları düştü, otomobil arzı arttı.', 'Otomobil talebi arttı, bu yüzden fiyatlar düştü.', 'Otomobil fiyatları düştü, talep eğrisi sağa kaydı.'], 'Fiyat değişmesi talep eğrisini kaydırmaz; yalnızca talep edilen miktarı değiştirir. "Talep arttı" demek eğrinin kayması anlamına gelir.'),
  ('Fiyat yükseldiğinde üreticilerin daha fazla arz etmesinin temel nedeni hangisidir?', 'Daha yüksek fiyatın, artan marjinal maliyetleri karşılayıp üretimi kârlı kılması', ['Tüketicilerin daha fazla talep etmesi', 'Devletin üreticileri zorunlu tutması', 'Üretim maliyetlerinin fiyat yükseldikçe kendiliğinden ve hızla düşmesi'], 'Üretim arttıkça marjinal maliyet genellikle yükselir; ek birimleri üretmek ancak daha yüksek fiyatla kârlı olur.'),
  ('Bir malın arz fonksiyonu Qs = 5P − 20 biçimindedir. Fiyat 12 TL olduğunda arz edilen miktar kaçtır?', '40', ['60', '80', '32'], 'Qs = 5 × 12 − 20 = 60 − 20 = 40 birimdir.'),
  ('Kuraklık nedeniyle bir yılda fındık rekoltesinin düşmesi fındık piyasasını nasıl etkiler?', 'Arz eğrisi sola kayar.', ['Arz eğrisi sağa kayar.', 'Talep eğrisi sağa kayar.', 'Arz eğrisi üzerinde aşağı hareket olur.'], 'Doğal koşullar tarımda arzı belirleyen önemli bir etkendir; kuraklık her fiyatta daha az fındık sunulmasına yol açar.'),
  ('Bir çiftçi aynı tarlada buğday ya da mısır yetiştirebilmektedir. Mısırın fiyatı belirgin biçimde artarsa buğday arzına ne olması beklenir?', 'Buğday arzı azalır.', ['Buğday arzı artar.', 'Buğday talebi artar.', 'Buğday arzı değişmez.'], 'Mısır ile buğday üretimde birbirinin ikamesidir. Mısır daha kârlı hâle gelince kaynaklar mısıra kayar ve buğday arzı azalır.'),
  ('Üreticiler gelecekte ürünlerinin fiyatının yükseleceğini bekliyorsa ve ürün depolanabiliyorsa bugünkü arza ne olur?', 'Bugünkü arz azalır.', ['Bugünkü arz artar.', 'Bugünkü talep azalır.', 'Bugünkü arz değişmez.'], 'Üreticiler malı ileride daha yüksek fiyattan satmak için stokta tutar; bu da bugünkü arzı azaltır.'),
  ('Bir piyasada talep Qd = 100 − 2P, arz Qs = 3P − 50 olarak verilmiştir. Denge fiyatı kaç TL\'dir?', '30 TL', ['25 TL', '50 TL', '40 TL'], '100 − 2P = 3P − 50 eşitliğinden 5P = 150 ve P = 30 TL bulunur.'),
  ('Talebin Qd = 60 − P, arzın Qs = 2P − 30 olduğu bir piyasada denge miktarı kaç birimdir?', '30', ['20', '40', '15'], '60 − P = 2P − 30 ise 3P = 90, P = 30 olur. Denge miktarı Q = 60 − 30 = 30 birimdir.'),
  ('Piyasa dengesi için aşağıdakilerden hangisi söylenebilir?', 'Dışarıdan bir etki olmadıkça fiyatın değişme eğilimi yoktur.', ['Fiyatın devlet tarafından belirlendiği tek noktadır ve sürekli değiştirilir.', 'Arz eğrisinin dikey eksenle kesiştiği noktadır.', 'Tüm alıcıların malı ücretsiz edindiği noktadır.'], 'Dengede ne fazla arz ne de fazla talep vardır; bu nedenle fiyatı yukarı ya da aşağı iten bir baskı bulunmaz.'),
  ('Bir piyasada arz fazlası varsa serbest piyasa koşullarında ne olması beklenir?', 'Satıcılar stoklarını eritmek için fiyatı düşürür.', ['Alıcılar malı alabilmek için fiyatı yükseltmeye razı olur.', 'Üreticiler üretimi artırarak fiyatın yükselmesini sağlar.', 'Fiyat hiç değişmez, fazla mal yok edilir.'], 'Satılamayan mallar fiyatı aşağı çeker; fiyat düştükçe talep edilen miktar artar, arz edilen miktar azalır ve denge yeniden kurulur.'),
  ('Talebin Qd = 200 − 5P, arzın Qs = 5P olduğu bir piyasada fiyat 15 TL\'de tutulursa ne kadarlık fark oluşur?', '50 birimlik talep fazlası', ['50 birimlik arz fazlası', '75 birimlik talep fazlası', '125 birimlik arz fazlası'], 'P = 15 için Qd = 200 − 75 = 125, Qs = 75 olur. Talep edilen miktar 50 birim fazladır; denge fiyatı 20 TL\'dir.'),
  ('Bir malın talebi artarken arzı değişmezse denge fiyatı ve miktarı nasıl değişir?', 'İkisi de artar.', ['Fiyat artar, miktar azalır.', 'Fiyat azalır, miktar artar.', 'İkisi de azalır.'], 'Talep eğrisi sağa kayınca aynı arz eğrisi üzerinde daha yüksek bir fiyat ve daha büyük bir miktarda yeni denge oluşur.'),
  ('Arz eğrisi sağa kayarken talep sabit kalırsa yeni dengede ne olur?', 'Fiyat düşer, miktar artar.', ['Fiyat artar, miktar azalır.', 'Fiyat ve miktar birlikte artar.', 'Fiyat ve miktar birlikte azalır.'], 'Arz artışı aynı fiyatta arz fazlası yaratır; fiyat düşer ve talep edilen miktar artarak yeni dengeye ulaşılır.'),
  ('Don olayı nedeniyle portakal arzı azalırsa portakal piyasasında ne beklenir?', 'Fiyat yükselir, satılan miktar azalır.', ['Fiyat düşer, satılan miktar artar.', 'Fiyat ve miktar değişmez.', 'Fiyat düşer, satılan miktar azalır.'], 'Arzın azalması (sola kayma) eski fiyatta talep fazlası yaratır; fiyat yükselir ve denge miktarı azalır.'),
  ('Bir kentte elektrikli otomobillere ilgi artarken aynı dönemde batarya üretim maliyetleri belirgin biçimde düşmüştür. Elektrikli otomobil piyasasında kesin olarak ne beklenir?', 'Satılan araç sayısının artması', ['Araç fiyatlarının kesinlikle yükselmesi', 'Araç fiyatlarının kesinlikle düşmesi', 'Satılan araç sayısının azalması'], 'Talep artışı ve arz artışı ikisi de miktarı artırır; fiyat ise iki kaymanın büyüklüğüne göre artabilir ya da düşebilir.'),
  ('Piyasada talep fazlası olduğunda fiyatın yükselmesi dengeye nasıl katkı sağlar?', 'Talep edilen miktarı azaltıp arz edilen miktarı artırarak', ['Arz edilen miktarı azaltıp talep edilen miktarı artırarak dengeye iterek', 'Yalnızca talep eğrisini sola kaydırarak', 'Yalnızca arz eğrisini sağa kaydırarak'], 'Yükselen fiyat eğriler üzerinde hareket yaratır: alıcılar daha az, satıcılar daha çok ister ve fark kapanır.'),
  ('Bir malın fiyatı %10 arttığında talep edilen miktarı %25 azalmıştır. Talebin fiyat esnekliğinin mutlak değeri kaçtır?', '2,5', ['0,4', '1,5', '25'], 'Esneklik = %25 / %10 = 2,5 olur. 1\'den büyük olduğu için talep esnektir.'),
  ('Fiyatı %20 düşen bir malın talep edilen miktarı yalnızca %5 artmıştır. Bu malın talebi için ne söylenir?', 'İnelastiktir (esnek değildir).', ['Esnektir, çünkü esneklik 4\'tür.', 'Birim esnektir, çünkü değişmeler aynı yöndedir.', 'Tam esnektir, çünkü talep sonsuz duyarlıdır.'], 'Esneklik = 5 / 20 = 0,25 olup 1\'den küçüktür; tüketiciler fiyata az tepki verir.'),
  ('Aşağıdaki mallardan hangisinin talebi fiyata karşı genellikle en az esnektir?', 'İnsülin gibi hayati ilaçlar', ['Belirli bir markanın meyve suyu', 'Yurt dışı tatil paketleri', 'Sinema biletleri'], 'Zorunlu olan ve yakın ikamesi bulunmayan malların talebi fiyat değişmelerine az duyarlıdır.'),
  ('Bir malın yakın ikamelerinin çok olması talebin fiyat esnekliğini nasıl etkiler?', 'Esnekliği artırır.', ['Esnekliği azaltır ve sıfıra yaklaştırır.', 'Esneklik üzerinde hiçbir etkisi olmaz.', 'Talebin yönünü pozitif hâle getirir.'], 'İkame mal bol olduğunda fiyat artışında tüketiciler kolayca başka mala geçer; bu nedenle talep daha esnek olur.'),
  ('Talep eğrisi tamamen dikey olan bir malın fiyat esnekliği kaçtır?', 'Sıfır', ['Bir', 'Sonsuz', 'Eksi bir'], 'Dikey talep eğrisinde fiyat ne olursa olsun talep edilen miktar değişmez; buna tam inelastik talep denir.'),
  ('Talebi inelastik olan bir malda fiyat artırılırsa satıcıların toplam hasılatına ne olur?', 'Artar.', ['Azalır.', 'Değişmez.', 'Sıfıra iner.'], 'İnelastik talepte miktardaki yüzde düşüş fiyattaki yüzde artıştan küçüktür; fiyat × miktar yükselir.'),
  ('Talebi esnek olan bir mal için fiyat indirimi toplam hasılatı nasıl etkiler?', 'Toplam hasılatı artırır.', ['Toplam hasılatı azaltır.', 'Toplam hasılatı değiştirmez.', 'Önce artırır sonra kesinlikle sıfıra indirir.'], 'Esnek talepte fiyat %1 düşünce miktar %1\'den fazla artar; bu yüzden toplam harcama ve hasılat yükselir.'),
  ('Bir sinema salonu bilet fiyatını düşürdüğü hâlde bilet hasılatı değişmemiştir. Bu fiyat aralığında talep için ne söylenebilir?', 'Birim esnektir.', ['Tam inelastiktir.', 'Esnektir ve esneklik 1\'den büyüktür.', 'Talep eğrisi pozitif eğimlidir.'], 'Fiyat değişmesine rağmen toplam hasılatın sabit kalması, miktar ve fiyattaki yüzde değişmelerin eşit olduğunu yani esnekliğin 1 olduğunu gösterir.'),
  ('Toplam hasılat nasıl hesaplanır?', 'Fiyat ile satılan miktarın çarpımıyla', ['Toplam maliyetten kârın çıkarılmasıyla', 'Fiyatın satılan miktara bölünmesiyle', 'Marjinal maliyetle miktarın toplamıyla'], 'Toplam hasılat (TR) = P × Q\'dur; firmanın satışlardan elde ettiği toplam gelirdir.'),
  ('Gelir %10 arttığında bir malın talebi %15 artmıştır. Bu mal için ne söylenebilir?', 'Lüks bir normal maldır.', ['Zorunlu bir normal maldır ve gelir esnekliği 0,67\'dir.', 'Düşük bir maldır ve gelir esnekliği negatiftir.', 'Gelirden bağımsız, gelir esnekliği sıfır olan bir maldır.'], 'Gelir esnekliği 15 / 10 = 1,5\'tir. 1\'den büyük gelir esnekliği malın lüks olduğunu gösterir.'),
  ('Gelir esnekliği 0 ile 1 arasında olan mallar nasıl sınıflandırılır?', 'Zorunlu mallar', ['Lüks mallar', 'Düşük mallar', 'Giffen malları'], 'Bu mallar normal maldır ama talepleri gelirden daha yavaş artar; ekmek ve temel gıdalar örnek verilebilir.'),
  ('İki mal arasındaki çapraz fiyat esnekliği negatif ise bu mallar için ne söylenir?', 'Tamamlayıcıdırlar.', ['İkame mallardır.', 'Birbirinden bağımsızdırlar.', 'İkisi de düşük maldır.'], 'Bir malın fiyatı artınca diğerinin talebi azalıyorsa mallar birlikte tüketilmektedir; çapraz esneklik negatiftir.'),
  ('A malının fiyatı %8 arttığında B malının talebi %4 artmıştır. A ile B arasındaki çapraz esneklik ve ilişki hangisidir?', '+0,5; ikame mallar', ['−0,5; tamamlayıcı mallar', '+2; tamamlayıcı mallar', '−2; ikame mallar'], 'Çapraz esneklik = %4 / %8 = +0,5\'tir. Pozitif işaret, A pahalanınca tüketicilerin B\'ye yöneldiğini yani ikame ilişkisini gösterir.'),
  ('Çapraz fiyat esnekliği sıfıra yakın çıkan iki mal için hangi yorum yapılır?', 'Mallar birbirinden bağımsızdır.', ['Mallar güçlü ikamedir.', 'Mallar güçlü tamamlayıcıdır.', 'İki mal da gösteriş amacıyla tüketilen Veblen malıdır.'], 'Bir malın fiyat değişmesi diğerinin talebini etkilemiyorsa mallar arasında anlamlı bir ilişki yoktur; örneğin ayakkabı ve tuz.'),
  ('Antika tablolar ya da ünlü bir ressamın eserleri gibi miktarı artırılamayan malların arz esnekliği için ne söylenir?', 'Sıfırdır; arz eğrisi dikeydir.', ['Sonsuzdur; arz eğrisi yataydır.', 'Birdir; arz eğrisi 45 derecedir.', 'Negatiftir; arz eğrisi aşağı eğimlidir.'], 'Fiyat ne kadar yükselirse yükselsin yeni eser üretilemediği için arz edilen miktar sabittir; arz tam inelastiktir.'),
  ('Aşağıdaki etkenlerden hangisi bir malın arz esnekliğini artırır?', 'Üretimin kısa sürede ve kolayca artırılabilmesi', ['Üretim için çok uzun süre gerekmesi', 'Ürünün tüketici bütçesinde küçük pay tutması', 'Kullanılan girdilerin çok kıt olması'], 'Üretim kapasitesi esnekse ve girdiler kolay bulunuyorsa üreticiler fiyat artışına hızla yanıt verebilir.'),
  ('Bir malın fiyatı %5 arttığında arz edilen miktar %15 artmıştır. Arz esnekliği kaçtır?', '3', ['0,33', '10', '1,5'], 'Arz esnekliği = %15 / %5 = 3\'tür; arz esnektir.'),
  ('Ayşe bir kitap için en çok 250 TL ödemeye razıdır ve kitabı 180 TL\'ye satın almıştır. Ayşe\'nin bu alışverişteki tüketici rantı kaç TL\'dir?', '70 TL', ['180 TL', '250 TL', '430 TL'], 'Tüketici rantı = ödemeye razı olunan tutar − ödenen fiyat = 250 − 180 = 70 TL.'),
  ('Bir üretici bir malı en az 60 TL\'ye satmaya razıdır ve piyasada 95 TL\'ye satmıştır. Bu satıştaki üretici rantı kaçtır?', '35 TL', ['60 TL', '95 TL', '155 TL'], 'Üretici rantı = satış fiyatı − satıcının kabul edeceği en düşük fiyat = 95 − 60 = 35 TL.'),
  ('Bir piyasadaki toplam artık (toplam refah) nasıl tanımlanır?', 'Tüketici rantı ile üretici rantının toplamı', ['Toplam hasılat ile toplam maliyetin toplamının ikiye bölünmesi', 'Vergi geliri ile kârın farkı', 'Arz fazlası ile talep fazlasının toplamı'], 'Toplam artık, alıcıların değerlemesi ile satıcıların maliyeti arasındaki farkın tamamıdır; tüketici ve üretici rantlarının toplamına eşittir.'),
  ('Tavan fiyatın piyasada etkili (bağlayıcı) olabilmesi için nasıl belirlenmesi gerekir?', 'Denge fiyatının altında', ['Denge fiyatının üzerinde', 'Denge fiyatına tam eşit', 'Üretim maliyetinin iki katında'], 'Dengenin üzerindeki bir tavan fiyat zaten oluşan fiyatı kısıtlamaz. Ancak dengenin altında kalırsa piyasa fiyatını etkiler ve talep fazlası doğurur.'),
  ('Bağlayıcı bir tavan fiyat uygulamasının en olası yan etkisi hangisidir?', 'Kuyrukların oluşması ve karaborsanın ortaya çıkması', ['Depolarda satılamayan mal birikmesi', 'Üretimin hızla artması ve fiyatların kendiliğinden düşmesi', 'Malın kalitesinin kendiliğinden yükselmesi'], 'Fiyat dengenin altında tutulunca talep fazlası oluşur. Malı bulamayanlar kuyruğa girer ya da yasal fiyatın üzerinde gizlice satış yapılır.'),
  ('Denge fiyatının üzerinde belirlenen bir taban fiyat piyasada ne doğurur?', 'Arz fazlası', ['Talep fazlası', 'Karaborsa ve kuyruk', 'Fiyatların düşmesi'], 'Yüksek fiyatta üreticiler çok, tüketiciler az ister. Ortaya çıkan fazla ürün genellikle devletin destekleme alımıyla stoklanır.'),
  ('Yasal olarak belirlenen fiyatın dışında, yasa dışı biçimde ve genellikle daha yüksek fiyatla yapılan alışverişe ne ad verilir?', 'Karaborsa', ['Serbest bölge', 'Açık artırma', 'Destekleme alımı'], 'Bağlayıcı tavan fiyatlar talep fazlası yarattığından, mala ulaşmak isteyenlerle satıcılar arasında yasa dışı bir piyasa doğabilir.'),
  ('Bir mala satıcıdan alınan birim başına sabit bir vergi konduğunda arz eğrisi nasıl etkilenir?', 'Vergi tutarı kadar yukarı (sola) kayar.', ['Vergi tutarı kadar aşağı (sağa) kayar.', 'Değişmez; vergi yalnızca talep eğrisini kaydırır.', 'Dikey hâle gelir.'], 'Satıcılar her birim için devlete vergi ödeyeceğinden, aynı miktarı ancak vergi kadar daha yüksek fiyatla sunmaya razı olur.'),
  ('Birim başına vergi konan bir piyasada vergi yükünün daha büyük kısmını hangi taraf taşır?', 'Daha az esnek olan taraf', ['Her zaman satıcılar', 'Her zaman vergiyi devlete yasal olarak ödeyen alıcılar', 'Daha esnek olan taraf'], 'Fiyata daha az tepki veren taraf vergiden kaçamaz; bu yüzden yükün büyük bölümü daha inelastik olan tarafa düşer. Yükün kimden tahsil edildiği bunu değiştirmez.'),
  ('Bir vergi nedeniyle gerçekleşmeyen ve hiç kimsenin eline geçmeyen refah kaybına ne ad verilir?', 'Ölü ağırlık kaybı', ['Tüketici rantı', 'Fırsat maliyeti', 'Batık maliyet'], 'Vergi işlem miktarını azaltır; artık yapılmayan karşılıklı yararlı alışverişlerin kaybı ne devlete ne tarafların cebine geçer.'),
  ('Devletin üreticilere birim başına sübvansiyon (destek ödemesi) vermesinin piyasa dengesine etkisi hangisidir?', 'Arz artar; fiyat düşer, miktar artar.', ['Arz azalır; fiyat artar, miktar azalır.', 'Talep azalır; fiyat ve miktar düşer.', 'Hiçbir değişme olmaz.'], 'Sübvansiyon üreticinin birim maliyetini düşürmüş gibi etki yapar ve arz eğrisini aşağı (sağa) kaydırır.'),
  ('Sigara gibi talebi inelastik bir mala vergi konmasının devletin vergi geliri açısından avantajı nedir?', 'Satış miktarı az düştüğü için yüksek ve istikrarlı gelir sağlar.', ['Satışları tamamen durdurduğu için gelir sıfıra iner.', 'Vergi yükünün tamamını tüketicilerden alıp üreticilere yükler.', 'Ölü ağırlık kaybını sıfırın altına indirir.'], 'İnelastik talepte vergi sonrası miktar çok az azalır; vergi tabanı korunduğu için gelir yüksek kalır.'),
  ('Bir tüketicinin dondurma tüketiminden sağladığı toplam fayda 1., 2. ve 3. külah için sırasıyla 20, 35 ve 45\'tir. Üçüncü külahın marjinal faydası kaçtır?', '10', ['45', '15', '25'], 'Marjinal fayda = 45 − 35 = 10\'dur. İkinci külahınki ise 15\'tir; marjinal fayda azalmaktadır.'),
  ('Marjinal fayda sıfıra eşit olduğunda toplam fayda için ne söylenir?', 'En yüksek düzeyine ulaşmıştır.', ['Sıfıra inmiştir.', 'Hızla artmaya devam etmektedir.', 'Negatif değerdedir.'], 'Marjinal fayda pozitif oldukça toplam fayda artar; sıfır olduğunda toplam fayda en büyük değerdedir, negatife dönünce azalmaya başlar.'),
  ('Fayda kavramı ekonomide en doğru biçimde nasıl tanımlanır?', 'Bir malın tüketiminden elde edilen tatmin', ['Bir malın piyasadaki fiyatı', 'Bir malın üretilmesi için katlanılan toplam maliyet', 'Bir malın ağırlığı ve dayanıklılığı'], 'Fayda, kişinin bir mal ya da hizmeti tüketerek ihtiyacını gidermesinden duyduğu öznel tatmindir.'),
  ('Geliri 600 TL olan bir öğrenci yalnızca kitap (tanesi 60 TL) ve sinema bileti (tanesi 30 TL) almaktadır. Hiç kitap almazsa en çok kaç sinema bileti alabilir?', '20', ['10', '30', '15'], 'Gelirin tamamı bilete harcanırsa 600 / 30 = 20 bilet alınabilir; bu, bütçe doğrusunun bilet eksenini kestiği noktadır.'),
  ('Tüketicinin geliri iki katına çıkarken iki malın fiyatı da iki katına çıkarsa bütçe doğrusuna ne olur?', 'Değişmez.', ['Dışa doğru paralel kayar.', 'İçe doğru paralel kayar.', 'Eğimi iki katına çıkar.'], 'Gelir ve tüm fiyatlar aynı oranda değişince satın alınabilecek miktarlar ve fiyat oranı aynı kalır; bütçe doğrusu yerinden oynamaz.'),
  ('Fiyatlar sabitken tüketicinin geliri artarsa bütçe doğrusu nasıl değişir?', 'Eğimi değişmeden dışa doğru paralel kayar.', ['Eğimi dikleşerek içe doğru döner.', 'Yalnızca tek bir eksen üzerinde dışa doğru döner, diğeri sabit kalır.', 'Kayıtsızlık eğrisiyle çakışır.'], 'Gelir artışı her iki maldan da daha çok almayı mümkün kılar. Fiyat oranı aynı kaldığından eğim değişmez.'),
  ('Tüketiciye aynı fayda düzeyini sağlayan iki mal bileşimlerini gösteren eğriye ne ad verilir?', 'Kayıtsızlık eğrisi', ['Bütçe doğrusu', 'Üretim imkânları eğrisi', 'Eş maliyet doğrusu'], 'Kayıtsızlık eğrisi üzerindeki her bileşim tüketiciye eşit fayda verir; tüketici bunlar arasında kayıtsızdır.'),
  ('Bütçe doğrusu X ekseninde 40 birim, Y ekseninde 20 birim değerindedir. X malının fiyatı 5 TL ise tüketicinin geliri kaç TL\'dir?', '200 TL', ['100 TL', '800 TL', '400 TL'], 'Gelirin tamamı X\'e harcandığında 40 birim alınıyorsa gelir 40 × 5 = 200 TL\'dir. Buradan Y\'nin fiyatı 10 TL bulunur.'),
  ('Yalnızca X malının fiyatı düşerse bütçe doğrusu nasıl değişir?', 'X eksenindeki kesim noktası dışa kayar, Y eksenindeki sabit kalır.', ['İki eksendeki kesim noktası da aynı oranda dışa doğru paralel kayar.', 'Y eksenindeki kesim noktası dışa kayar, X sabit kalır.', 'Bütçe doğrusu hiç değişmez.'], 'Gelirin tamamı X\'e harcandığında artık daha fazla X alınabilir; Y\'nin fiyatı değişmediği için Y kesimi aynı kalır ve doğru döner.'),
  ('Bir atölyede 4 işçi günde 100 gömlek üretmektedir. Emeğin ortalama ürünü kaç gömlektir?', '25', ['100', '400', '20'], 'Ortalama ürün = toplam ürün / işçi sayısı = 100 / 4 = 25 gömlektir.'),
  ('Bir fırında 3 işçiyle günde 210 ekmek, 4 işçiyle 260 ekmek üretilmektedir. Dördüncü işçinin marjinal ürünü kaçtır?', '50', ['65', '70', '260'], 'Marjinal ürün = 260 − 210 = 50 ekmektir. Ortalama ürün ise 4 işçide 65\'tir.'),
  ('Bir girdinin marjinal ürünü negatif olduğunda üretimde ne gözlenir?', 'O girdiyi artırmak toplam üretimi azaltır.', ['O girdiyi artırmak toplam üretimi hızla artırır.', 'Ortalama ürün en yüksek düzeyindedir.', 'Firmanın sabit maliyeti sıfırlanır.'], 'Örneğin küçük bir mutfağa çok fazla aşçı konunca birbirlerinin işini engellerler ve toplam üretim düşer.'),
  ('Azalan verimler kanununun geçerli olması için hangi koşul gereklidir?', 'En az bir üretim faktörünün sabit tutulması', ['Tüm üretim faktörlerinin aynı oranda ve aynı anda artırılması', 'Teknolojinin sürekli gelişmesi', 'Malın fiyatının sabit olması'], 'Kanun kısa dönemle ilgilidir; değişken girdi sabit girdiyle birleştirildikçe her birime düşen sabit girdi azalır.'),
  ('Bir çiftlikte sırasıyla 1., 2., 3. ve 4. işçiyle toplam üretim 10, 25, 35 ve 40 ton olmaktadır. Azalan verimler hangi işçiden itibaren başlamaktadır?', 'Üçüncü işçiden', ['İkinci işçiden', 'Dördüncü işçiden', 'Birinci işçiden'], 'Marjinal ürünler 10, 15, 10 ve 5 tondur. Marjinal ürün ikinci işçide en yüksek düzeye çıkıp üçüncü işçiden itibaren azalmaya başlar.'),
  ('Azalan verimler kanununun maliyetler üzerindeki yansıması hangisidir?', 'Bir noktadan sonra marjinal maliyetin artması', ['Sabit maliyetin sürekli artması', 'Ortalama değişken maliyetin hep sabit kalması', 'Tüm maliyetlerin sıfıra inmesi'], 'Her ek işçi daha az ek ürün sağladığında, bir birim daha üretmek için gereken ek maliyet yükselir.'),
  ('Ekonomideki kısa dönem ve uzun dönem ayrımı için hangisi doğrudur?', 'Takvim süresine değil, girdilerin değişebilirliğine dayanır.', ['Kısa dönem her zaman bir yıldan azdır.', 'Uzun dönem her zaman ve her sektörde on yıldan fazladır.', 'Tüm sektörlerde aynı süreyi gösterir.'], 'Bir kafe için uzun dönem birkaç ay olabilirken bir enerji santrali için on yıllar sürebilir; belirleyici olan tüm girdilerin ayarlanabilmesidir.'),
  ('Bir otomobil fabrikası siparişleri karşılamak için fazla mesai yaptırıyor ama yeni bir üretim hattı kurmaya zaman bulamıyor. Fabrika hangi dönemde karar vermektedir?', 'Kısa dönemde', ['Uzun dönemde', 'Durgunluk döneminde', 'Dönemden bağımsız olarak'], 'Emek artırılabiliyor ama üretim hattı (sermaye) sabit; bu da kısa dönemin tanımıdır.'),
  ('Bir ekmek fırınında yeni bir fırın makinesi alındıktan sonra aynı sayıda işçiyle daha çok ekmek üretilmeye başlanmıştır. Bu gelişme nasıl yorumlanır?', 'Emeğin marjinal ve ortalama ürünü artmıştır.', ['Azalan verimler kanunu ortadan kalkmıştır.', 'Emeğin ortalama ürünü azalmıştır.', 'Firmanın kısa dönemi sona ermiştir ve maliyet sıfırlanmıştır.'], 'Sermaye artışı her işçinin çalışabileceği araç miktarını artırır; bu da emeğin verimliliğini yükseltir.'),
  ('Bir firmanın sabit maliyeti 2.000 TL, 100 birim üretimdeki değişken maliyeti 3.000 TL\'dir. Ortalama toplam maliyet kaç TL\'dir?', '50 TL', ['30 TL', '20 TL', '5.000 TL'], 'Toplam maliyet 2.000 + 3.000 = 5.000 TL\'dir; ortalama toplam maliyet 5.000 / 100 = 50 TL olur.'),
  ('Bir firmanın toplam maliyeti 50 birim üretimde 4.000 TL, 51 birim üretimde 4.060 TL\'dir. 51. birimin marjinal maliyeti kaçtır?', '60 TL', ['80 TL', '4.060 TL', '79,6 TL'], 'Marjinal maliyet = 4.060 − 4.000 = 60 TL\'dir; bir birim fazla üretmenin toplam maliyete eklediği tutardır.'),
  ('Üretim miktarı arttıkça ortalama sabit maliyete ne olur?', 'Sürekli azalır.', ['Sürekli artar.', 'Önce azalır sonra artar.', 'Hiç değişmez.'], 'Sabit maliyet değişmezken daha çok birime bölündüğü için birim başına düşen sabit maliyet sürekli düşer.'),
  ('Kısa dönemde ortalama toplam maliyet eğrisinin U biçiminde olmasının temel nedeni nedir?', 'Önce sabit maliyetin yayılması, sonra azalan verimlerin etkisi', ['Talebin önce artıp sonra azalması', 'Devletin vergi oranlarını her yıl farklı oranlarda değiştirmesi', 'Tüketici zevklerinin zamanla değişmesi'], 'Başlangıçta sabit maliyet daha çok birime yayılarak ortalamayı düşürür; sonra azalan verimler nedeniyle değişken maliyetler hızla artar ve ortalama yükselir.'),
  ('Toplam maliyet ile ilgili aşağıdaki eşitliklerden hangisi doğrudur?', 'Toplam maliyet = sabit maliyet + değişken maliyet', ['Toplam maliyet = marjinal maliyet × fiyat', 'Toplam maliyet = toplam hasılat + firmanın ekonomik kârı', 'Toplam maliyet = ortalama maliyet / miktar'], 'Kısa dönemde toplam maliyet, üretimden bağımsız sabit giderlerle üretime bağlı değişken giderlerin toplamıdır.'),
  ('Bir firmanın aşırı büyümesiyle yönetim ve koordinasyon güçleşerek birim maliyetlerin artmasına ne denir?', 'Ölçek eksi ekonomisi', ['Ölçek ekonomisi', 'Kapsam ekonomisi', 'Ağ etkisi'], 'Çok büyük örgütlerde iletişim, denetim ve bürokrasi sorunları birim maliyeti yükseltebilir.'),
  ('Bir firma tüm girdilerini iki katına çıkardığında üretimi üç katına çıkmıştır. Bu durum neyi gösterir?', 'Ölçeğe göre artan getiri', ['Ölçeğe göre sabit getiri', 'Ölçeğe göre azalan getiri', 'Azalan verimler kanunu'], 'Girdiler belirli bir oranda artırıldığında çıktı daha büyük oranda artıyorsa ölçeğe göre artan getiri vardır.'),
  ('Bir firma tüm girdilerini %50 artırdığında üretimi %30 artmıştır. Firmanın karşılaştığı durum hangisidir?', 'Ölçeğe göre azalan getiri', ['Ölçeğe göre artan getiri', 'Ölçeğe göre sabit getiri', 'Kısa dönem azalan verim'], 'Çıktı girdilerden daha düşük oranda arttığı için ölçeğe göre getiri azalandır.'),
  ('Aşağıdakilerden hangisi ölçek ekonomisinin kaynaklarından biri değildir?', 'Yönetim kademelerinin aşırı artması', ['Hammaddenin toplu alımla ucuza alınması', 'İşçilerin dar görevlerde uzmanlaşması', 'Büyük makinelerin tam kapasiteyle kullanılması'], 'Aşırı yönetim kademesi koordinasyonu güçleştirir; bu ölçek eksi ekonomisinin nedenidir, ölçek ekonomisinin değil.'),
  ('Bir firma üretimini sıfıra indirse bile kısa dönemde hangi maliyetle karşılaşmaya devam eder?', 'Sabit maliyet', ['Değişken maliyet', 'Marjinal maliyet', 'Hammadde maliyeti'], 'Kira, sigorta ve sözleşmeli giderler gibi sabit maliyetler üretim yapılmasa da kısa dönemde ödenmeye devam eder.'),
  ('Ekonomik kâr hesaplanırken muhasebe kârından farklı olarak neler de maliyete eklenir?', 'Örtük maliyetler', ['Yalnızca vergiler ve harçlar', 'Yalnızca hammadde giderleri', 'Sadece geçmiş yıllarda yapılan reklam giderleri'], 'Ekonomik kâr = toplam hasılat − (açık maliyetler + örtük maliyetler). Girişimcinin kendi emek ve sermayesinin fırsat maliyeti örtük maliyettir.'),
  ('Bir kafe sahibinin yıllık hasılatı 900.000 TL, kira ve malzeme gibi açık giderleri 700.000 TL\'dir. Kafeyi işletmek yerine bir şirkette çalışsa yılda 250.000 TL kazanacaktır. Ekonomik kâr kaç TL\'dir?', '−50.000 TL', ['200.000 TL', '−250.000 TL', '450.000 TL'], 'Muhasebe kârı 900.000 − 700.000 = 200.000 TL\'dir. Vazgeçilen 250.000 TL maaş çıkarılınca ekonomik kâr −50.000 TL olur.'),
  ('Ekonomik kârın sıfır olduğu durumda firmanın elde ettiği kâra ne ad verilir?', 'Normal kâr', ['Aşırı kâr', 'Tekel kârı', 'Batık kâr'], 'Normal kâr, girişimcinin kaynaklarını bu işte tutmasına yetecek en düşük kazançtır; tüm fırsat maliyetleri karşılanmıştır.'),
  ('Aşağıdakilerden hangisi bir firmanın örtük maliyetine örnektir?', 'Sahibinin kendi binasını kiraya vermemesinden doğan kira kaybı', ['İşçilere ödenen aylık ücretler', 'Tedarikçiye ödenen ve faturaya bağlanan hammadde bedeli', 'Elektrik faturası için yapılan ödeme'], 'Örtük maliyetler para çıkışı gerektirmeyen ama vazgeçilen gelir anlamına gelen fırsat maliyetleridir.'),
  ('Bir firma kârını en yüksek yapan üretim miktarını hangi koşula göre seçer?', 'Marjinal hasılat = marjinal maliyet', ['Toplam hasılat = toplam maliyet + sabit maliyet', 'Ortalama maliyet = sıfır', 'Fiyat = sabit maliyet'], 'Marjinal hasılat marjinal maliyetten büyükse üretimi artırmak, küçükse azaltmak kârı yükseltir; en yüksek kâr ikisinin eşitlendiği noktadadır.'),
  ('Bir firma için bir birim daha üretmenin marjinal hasılatı 80 TL, marjinal maliyeti 65 TL\'dir. Kârını artırmak için ne yapmalıdır?', 'Üretimi artırmalıdır.', ['Üretimi azaltmalıdır.', 'Üretimi hemen durdurmalıdır.', 'Fiyatı marjinal maliyete indirmelidir.'], 'Ek birim maliyetinden 15 TL fazla gelir getiriyor; bu birimi üretmek toplam kârı artırır.'),
  ('Marjinal hasılatın marjinal maliyetten küçük olduğu bir üretim düzeyinde firma için ne söylenir?', 'Son birimler kârı azaltmaktadır.', ['Kâr en yüksek düzeydedir ve daha artırılamaz.', 'Üretimi artırmak kârı yükseltir.', 'Toplam hasılat mutlaka negatiftir.'], 'Ek birimlerin maliyeti getirdiği gelirden fazla olduğundan üretimi azaltmak kârı yükseltir.'),
  ('Ekonomide "marjinal analiz" denildiğinde ne kastedilir?', 'Ek bir birimin getirdiği fayda ile maliyetinin karşılaştırılması', ['Yalnızca ortalama değerlerin dikkate alınması', 'Geçmişte yapılmış bütün harcamaların toplanıp karşılaştırılması', 'Firmanın toplam varlıklarının sayılması'], 'Rasyonel kararlar "bir birim daha" ile ilgilidir: ek fayda ek maliyetten büyükse eylem sürdürülür.'),
  ('Bir firmanın toplam hasılatı 500.000 TL, açık maliyetleri 320.000 TL ve örtük maliyetleri 180.000 TL\'dir. Bu firma için hangisi doğrudur?', 'Normal kâr elde etmektedir.', ['Ekonomik zarar etmektedir.', 'Aşırı kâr elde etmektedir.', 'Muhasebe zararındadır.'], 'Ekonomik kâr = 500.000 − 320.000 − 180.000 = 0\'dır. Sıfır ekonomik kâr normal kâr demektir; muhasebe kârı ise 180.000 TL\'dir.'),
  ('Tam rekabet piyasasındaki tek bir firmaya neden "fiyat alıcı" denir?', 'Piyasa fiyatını etkileyecek büyüklükte değildir.', ['Fiyatı devlet her gün yeniden belirler.', 'Fiyatı yalnızca kendi maliyetine göre ve rakiplerinden bağımsız belirler.', 'Malını her zaman piyasa fiyatının üstünde satar.'], 'Firma piyasa içinde çok küçük olduğundan üretimini değiştirse de fiyat değişmez; piyasada oluşan fiyatı kabul eder.'),
  ('Tam rekabetteki tek bir firmanın karşılaştığı talep eğrisi nasıldır?', 'Piyasa fiyatı düzeyinde yatay', ['Negatif eğimli ve piyasa talebinden daha dik', 'Tamamen dikey', 'Pozitif eğimli'], 'Firma piyasa fiyatında istediği kadar satabilir; fiyatı biraz yükseltirse hiç satamaz. Bu da tam esnek, yatay bir talep eğrisi demektir.'),
  ('Tam rekabet piyasasındaki bir firma için fiyat, ortalama hasılat ve marjinal hasılat arasındaki ilişki nedir?', 'Üçü birbirine eşittir.', ['Marjinal hasılat fiyattan her zaman küçüktür.', 'Ortalama hasılat fiyatın iki katıdır.', 'Fiyat marjinal hasılattan her zaman küçüktür.'], 'Fiyat sabit olduğundan her ek birim satış tam olarak fiyat kadar ek hasılat getirir: P = AR = MR.'),
  ('Aşağıdaki piyasalardan hangisi tam rekabet piyasasına en çok yaklaşır?', 'Bir semt pazarında birçok çiftçinin sattığı domates', ['Bir kentteki tek doğal gaz dağıtım şirketi', 'Birkaç büyük firmanın bulunduğu yerli otomobil üretimi sektörü', 'Markalı spor ayakkabı piyasası'], 'Domates gibi standart bir tarım ürününde çok sayıda küçük satıcı vardır ve ürünler birbirine çok benzer.'),
  ('Tam rekabet piyasasındaki bir firma kısa dönemde fiyat ortalama değişken maliyetin altına düşerse ne yapar?', 'Üretimi durdurur.', ['Üretimini artırır.', 'Fiyatını yükseltir.', 'Sabit maliyetlerini sıfırlar.'], 'Fiyat ortalama değişken maliyeti bile karşılamıyorsa üretmek zararı büyütür; firma kapanarak zararını sabit maliyetle sınırlar.'),
  ('Tam rekabette firmanın kısa dönem arz eğrisi hangi eğrinin hangi kısmıdır?', 'Ortalama değişken maliyetin üzerindeki marjinal maliyet eğrisi', ['Ortalama sabit maliyet eğrisinin tamamı', 'Talep eğrisinin artan bölümü ile arz eğrisinin kesiştiği kısım', 'Toplam hasılat eğrisinin azalan bölümü'], 'Firma her fiyatta P = MC olacak miktarı üretir; ancak fiyat ortalama değişken maliyetin altındaysa hiç üretmez.'),
  ('Tam rekabetteki bir firmanın ürünü piyasada 25 TL\'ye satılıyor ve firma 400 birim satıyor. Bu firmanın ortalama hasılatı kaç TL\'dir?', '25 TL', ['400 TL', '10.000 TL', '16 TL'], 'Ortalama hasılat = toplam hasılat / miktar = (25 × 400) / 400 = 25 TL\'dir; tam rekabette ortalama hasılat fiyata eşittir.'),
  ('Aşağıdakilerden hangisi tekel oluşmasına yol açan giriş engellerinden biridir?', 'Patent hakkı', ['Çok sayıda küçük rakip', 'Homojen ürün', 'Tüketicilerin tam bilgiye sahip olması'], 'Patentler belirli bir süre buluşun üretim hakkını tek firmaya verir; diğerleri yasal olarak piyasaya giremez.'),
  ('Tekelci bir firmanın marjinal hasılatı neden fiyattan düşüktür?', 'Daha fazla satmak için tüm birimlerde fiyatı düşürmek zorunda olduğundan', ['Devlet tekellerden yüksek vergi aldığından', 'Tekelin maliyetleri her zaman sıfır olduğundan', 'Tekelin talep eğrisi tam rekabetteki gibi yatay olduğundan'], 'Negatif eğimli talep eğrisinde ek birim satabilmek için fiyat düşürülür; bu indirim önceki birimlere de uygulanınca ek hasılat fiyatın altında kalır.'),
  ('Tam rekabetle karşılaştırıldığında tekel piyasasında genellikle ne gözlenir?', 'Daha yüksek fiyat ve daha düşük üretim', ['Daha düşük fiyat ve daha yüksek üretim', 'Aynı fiyat ve aynı üretim', 'Daha düşük fiyat ve daha düşük üretim'], 'Tekel MR = MC kuralıyla rekabetçi düzeyden daha az üretir ve talep eğrisi üzerinden daha yüksek fiyat koyar.'),
  ('Bir tekelin piyasayı tek başına elinde tutmasını sağlayan bir üretim girdisinin tamamına sahip olması hangi engel türüdür?', 'Kilit kaynağın denetimi', ['Ölçek eksi ekonomisi', 'Serbest giriş', 'Fiyat alıcılık'], 'Bir maden ya da hammadde kaynağının tek bir firmanın elinde olması diğer firmaların üretim yapmasını engeller.'),
  ('Doğal tekel hangi durumda ortaya çıkar?', 'Tek bir firmanın tüm piyasayı birden fazla firmadan daha düşük maliyetle karşılayabildiği durumda', ['Devletin bir firmaya özel lisans ya da imtiyaz verdiği her durumda ve her sektörde', 'Bir firmanın patent aldığı durumda', 'Ürünlerin birbirinden çok farklı olduğu durumda'], 'Çok yüksek sabit maliyet ve geniş ölçek ekonomileri, tek firmayla üretimi en ucuz yol hâline getirir.'),
  ('Aşağıdakilerden hangisi doğal tekele en tipik örnektir?', 'Bir kentin su şebekesi', ['Mahalledeki fırınlar', 'Hazır giyim mağazaları', 'Taksi durakları'], 'Su şebekesinde boru hattının kurulması çok pahalıdır; ikinci bir şebeke kurmak kaynak israfı olur, bu yüzden tek firma en düşük maliyetle hizmet verir.'),
  ('Sinemaların öğrencilere indirimli bilet satması hangi uygulamaya örnektir?', 'Fiyat farklılaştırması', ['Tavan fiyat uygulaması', 'Kartel anlaşması', 'Tam rekabet fiyatlaması'], 'Öğrencilerin ödeme isteği ve fiyat esnekliği farklı olduğundan sinema bu gruba daha düşük fiyat uygular.'),
  ('Havayolu şirketlerinin aynı uçuş için aylar önce alınan biletleri ucuz, son gün alınanları pahalı satması neyi gösterir?', 'Ödeme isteği farklı yolculara farklı fiyat uygulandığını', ['Uçuşun işletme maliyetinin son gün iki katına çıktığını', 'Havayolu piyasasının tam rekabet olduğunu', 'Bilet fiyatlarının devlet tarafından belirlendiğini'], 'Son anda bilet alanlar çoğunlukla zorunlu iş yolculuğu yapar ve fiyata daha az duyarlıdır; şirket bunu fiyat farklılaştırmasıyla kullanır.'),
  ('Çok sayıda firmanın birbirine benzeyen ama marka, tasarım ya da hizmet bakımından farklılaştırılmış ürünler sattığı piyasa türü hangisidir?', 'Monopolcü rekabet', ['Tam rekabet', 'Saf tekel', 'Oligopol'], 'Monopolcü rekabette ürün farklılaştırması her firmaya küçük bir fiyat belirleme gücü verir, ancak giriş serbesttir.'),
  ('Aşağıdakilerden hangisi monopolcü rekabet piyasasına en uygun örnektir?', 'Bir kentteki çok sayıda kuaför salonu', ['Bir ülkedeki tek demiryolu işletmesi', 'Birkaç büyük firmanın hâkim olduğu uçak üretimi', 'Borsada işlem gören standart buğday'], 'Kuaförler hizmetlerini konum, üslup ve fiyatla farklılaştırır; sektörde çok sayıda firma vardır ve giriş kolaydır.'),
  ('Monopolcü rekabet piyasasında firmaların reklama ve marka oluşturmaya önemli harcamalar yapmasının temel nedeni nedir?', 'Ürünlerini rakiplerden farklı göstererek talebi artırmak', ['Tamamen homojen ürünlerini tüketicilere tanıtmak zorunda olmaları', 'Devletin reklam vermeyi zorunlu tutması', 'Fiyatların devletçe sabitlenmiş olması'], 'Farklılaşma, firmanın talep eğrisini sağa kaydırır ve fiyata karşı duyarlılığını azaltabilir.'),
  ('Oligopol piyasasındaki firmaların fiyat ve üretim kotası konusunda resmî bir anlaşma yaparak tekel gibi davranmasına ne ad verilir?', 'Kartel', ['Holding', 'Kooperatif', 'Konsorsiyum'], 'Kartel üyeleri toplam üretimi kısarak fiyatı yükseltir; çoğu ülkede rekabet hukukunca yasaklanır.'),
  ('Oligopol piyasalarında fiyatların uzun süre aynı düzeyde kalma eğilimi neyle açıklanabilir?', 'Fiyat indirimine rakiplerin de uyacağı, artırımına ise uymayacağı beklentisi', ['Firmaların maliyetlerinin hiç değişmemesi', 'Piyasada çok sayıda küçük ve fiyat alıcı firmanın bulunması', 'Ürünlerin hiç talep görmemesi'], 'Bükümlü talep yaklaşımına göre fiyat düşürmek pazar payı kazandırmaz, artırmak ise müşteri kaybettirir; bu da fiyatları katılaştırır.'),
  ('Bir piyasada tek bir alıcının bulunması durumuna ne ad verilir?', 'Monopson', ['Monopol', 'Duopol', 'Oligopol'], 'Monopsonda alıcı tektir ve satın aldığı faktörün ya da malın fiyatını etkileyebilir; tek büyük işverenin olduğu bir maden kasabası örnektir.'),
  ('Emek gibi üretim faktörlerine olan talebe neden "türetilmiş talep" denir?', 'Bu faktörlerle üretilen mallara olan talepten kaynaklandığı için', ['Ücretlerin ve faizlerin devlet tarafından yasa ile belirlendiği için', 'Faktörlerin fiyatı hiç değişmediği için', 'Yalnızca ithal mallardan oluştuğu için'], 'Firmalar işçiyi kendisi için değil, ürettiği mallar satılabildiği için talep eder; mallara talep artarsa emek talebi de artar.'),
  ('Bir ülkede yazılım ürünlerine talebin hızla artması yazılımcı emek piyasasını nasıl etkiler?', 'Yazılımcılara olan talep artar ve ücretler yükselme eğilimine girer.', ['Yazılımcı arzı hemen azalır ve ücret düşer.', 'Yazılımcı ücretleri değişmez çünkü emek talebi malların talebinden bağımsızdır.', 'Yazılımcıların marjinal ürünü sıfıra iner.'], 'Ürüne talep artınca ürünün fiyatı ve dolayısıyla emeğin marjinal ürün hasılatı yükselir; bu da emek talebini sağa kaydırır.'),
  ('Bir üretim sürecinin parçalara ayrılıp her işçinin yalnızca bir aşamayı yapmasına ne ad verilir?', 'İşbölümü', ['Ölçek eksi ekonomisi', 'Otomasyon vergisi', 'Dikey bütünleşme'], 'İşbölümünde her işçi belirli bir göreve odaklanır; bu da beceri kazanımını hızlandırır ve zaman kaybını azaltır.'),
  ('Aşağıdakilerden hangisi uzmanlaşmanın verimliliği artırma nedenlerinden biri değildir?', 'İşçilerin her gün farklı ve yeni işlere geçmesi', ['Tekrar yoluyla becerinin gelişmesi', 'İşler arası geçişlerde harcanan zaman kaybının azalması', 'Özel makinelerin kullanılabilmesi'], 'Uzmanlaşma aynı işin tekrarlanmasına dayanır; sürekli iş değiştirmek ise verimlilik kazancını ortadan kaldırır.'),
  ('Ali bir saatte 10 sayfa çeviri ya da 5 web sayfası tasarımı yapabiliyor; Zeynep ise bir saatte 4 sayfa çeviri ya da 4 web sayfası tasarımı yapabiliyor. Ortak bir projede iş nasıl bölüşülmelidir?', 'Ali çeviri, Zeynep tasarım yapmalıdır.', ['Ali tasarım, Zeynep çeviri yapmalıdır.', 'İkisi de yalnızca çeviri yapmalıdır.', 'Ali her işi yapmalı, Zeynep çalışmamalıdır.'], 'Ali için 1 tasarımın fırsat maliyeti 2 çeviri, Zeynep için 1 çeviridir. Zeynep tasarımda, Ali çeviride daha düşük fırsat maliyetine sahiptir.'),
  ('Bir fabrikanın atıklarını nehre bırakması sonucu balıkçıların avlarının azalması hangi kavrama örnektir?', 'Negatif dışsallık', ['Pozitif dışsallık', 'Kamusal mal', 'Ölçek ekonomisi'], 'Fabrikanın üretim maliyetine yansımayan ama balıkçılara zarar veren kirlilik negatif üretim dışsallığıdır.'),
  ('Bir arıcının arılarının komşu meyve bahçelerinin tozlaşmasına katkı sağlaması neye örnektir?', 'Pozitif dışsallık', ['Negatif dışsallık', 'Tekel gücü', 'Ahlaki tehlike'], 'Arıcının faaliyeti, karşılığında ödeme almadığı bir fayda yaratır; bu pozitif dışsallıktır.'),
  ('Negatif dışsallık yaratan bir malın serbest piyasada üretim miktarı için ne söylenir?', 'Toplumsal açıdan en uygun miktardan fazladır.', ['Toplumsal açıdan en uygun miktardan azdır.', 'Toplumsal açıdan tam olarak en uygun düzeydedir.', 'Her zaman sıfırdır.'], 'Üretici dışsal maliyeti hesaba katmadığından özel maliyeti toplumsal maliyetin altında kalır ve aşırı üretim olur.'),
  ('Bir apartmanda bir dairenin gece geç saatlere kadar yüksek sesle müzik çalması ekonomik olarak nasıl sınıflandırılır?', 'Tüketimden doğan negatif dışsallık', ['Üretimden doğan pozitif dışsallık', 'Kamusal malın sunulması', 'Fiyat farklılaştırması'], 'Müzik dinleyen kişinin tüketimi, karşılık ödenmeyen bir rahatsızlığı komşularına yansıtır.'),
  ('Bir kent yönetimi trafik sıkışıklığını azaltmak için kent merkezine giren araçlardan ücret almaya karar vermiştir. Bu politikanın ekonomik mantığı nedir?', 'Sürücülerin başkalarına yüklediği sıkışıklık maliyetini hesaba katmasını sağlamak', ['Toplu taşıma kullananlardan da daha fazla vergi toplayıp belediye gelirini artırmak', 'Araç satışlarını artırmak', 'Akaryakıt fiyatlarını düşürmek'], 'Her araç trafiği yavaşlatarak diğerlerine maliyet yükler. Giriş ücreti bu negatif dışsallığı fiyata yansıtır.'),
  ('Saf kamusal malların iki temel özelliği hangisinde doğru verilmiştir?', 'Tüketimde rakipsizlik ve dışlanamazlık', ['Rakiplik ve dışlanabilirlik', 'Dayanıklılık ve bir yerden başka bir yere taşınabilirlik', 'Homojenlik ve depolanabilirlik'], 'Bir kişinin tüketimi diğerlerinin tüketimini azaltmaz (rakipsizlik) ve bedel ödemeyenler tüketimden alıkonulamaz (dışlanamazlık).'),
  ('Kamusal malların serbest piyasada yeterince üretilmemesinin temel nedeni nedir?', 'Bedavacılık (free rider) sorunu', ['Talebin fiyat esnekliğinin çok yüksek olması', 'Üretim maliyetlerinin sıfır olması', 'Tüketicilerin bu mallara hiç ihtiyaç duymaması'], 'İnsanlar ödeme yapmadan da yararlanabileceklerini bildikleri için ödemekten kaçınır; özel firmalar da maliyetini karşılayacak geliri elde edemez.'),
  ('Bir sokak lambasının ışığından yoldan geçen herkes yararlanır ve bir kişinin yararlanması diğerinin yararını azaltmaz. Bu özellik hangisidir?', 'Tüketimde rakipsizlik', ['Tüketimde rakiplik', 'Dışlanabilirlik', 'Ölçeğe göre azalan getiri'], 'Bir kişinin tüketiminin başkalarının yararlanabileceği miktarı azaltmaması rakipsizliktir.'),
  ('Kalabalık olmayan, ücretsiz bir otoyol hangi mal türüne yakındır; yoğun trafik saatlerinde bu özelliği nasıl değişir?', 'Kamusal mala yakındır; sıkışıklıkta tüketimde rakip hâle gelir.', ['Özel maldır; sıkışık saatlerde ise saf kamusal mala dönüşür ve dışlanamaz.', 'Kulüp malıdır; sıkışıklıkta dışlanabilir hâle gelir.', 'Serbest maldır; sıkışıklıkta hiç değişmez.'], 'Boş yolda bir aracın varlığı diğerlerini etkilemez. Trafik yoğunlaştığında her ek araç diğerlerini yavaşlatır; rakipsizlik ortadan kalkar.'),
  ('Bir işlemde taraflardan birinin diğerinden daha fazla bilgiye sahip olmasına ne ad verilir?', 'Asimetrik bilgi', ['Tam bilgi', 'Kamusal bilgi', 'Simetrik risk'], 'Satıcı malın kalitesini, sigortalı kendi riskini daha iyi bilebilir; bu bilgi farkı piyasaların işleyişini bozabilir.'),
  ('Sağlık sigortasına en çok, sağlık sorunları olduğunu bilen kişilerin başvurması hangi soruna örnektir?', 'Ters seçim', ['Ahlaki tehlike', 'Bedavacılık', 'Ölçek eksi ekonomisi'], 'Ters seçim, sözleşme öncesindeki bilgi farkı nedeniyle yüksek riskli kişilerin piyasada orantısız biçimde yer almasıdır.'),
  ('Otomobilini kaskoya yaptıran bir sürücünün artık daha dikkatsiz park etmesi hangi kavramla açıklanır?', 'Ahlaki tehlike', ['Ters seçim', 'Dışlanamazlık', 'Fiyat katılığı'], 'Ahlaki tehlike, sözleşme sonrasında riskin bir kısmı başkasına geçince kişinin davranışını daha riskli hâle getirmesidir.'),
  ('Sigorta şirketlerinin muafiyet (kazada belli bir tutarı sigortalının ödemesi) uygulamasının amacı nedir?', 'Sigortalının dikkatli davranma güdüsünü korumak', ['Şirketin tüm hasarları ödemekten kaçınması ve kârını artırması', 'Sigorta primlerini herkes için sıfırlamak', 'Ters seçimi tamamen artırmak'], 'Hasarın bir kısmını kendisi karşılayacak olan sigortalı daha özenli davranır; bu ahlaki tehlikeyi azaltır.'),
  ('Alfred Marshall\'ın fiyatın arz mı yoksa talep mi tarafından belirlendiği tartışmasına verdiği yanıt hangi benzetmeyle bilinir?', 'Makasın iki ağzı', ['Görünmez el', 'Kapalı kutu', 'Ortak alanlar trajedisi'], 'Marshall, kâğıdı makasın üst ağzı mı alt ağzı mı keser diye sormanın anlamsız olduğunu söyleyerek fiyatı arz ve talebin birlikte belirlediğini anlatmıştır.'),
  ('"Ceteris paribus" ifadesi ekonomik çözümlemelerde ne anlama gelir?', 'Diğer koşullar sabitken', ['Her şey değişirken', 'Devlet müdahalesiyle', 'Uzun dönemde'], 'Ekonomistler bir değişkenin etkisini incelerken diğer etkenleri sabit varsayar; talep kanunu da bu varsayımla ifade edilir.'),
  ('Ekonomik modeller kurulurken gerçekliğin basitleştirilmesinin amacı nedir?', 'Temel ilişkileri ayrıştırıp anlaşılır kılmak', ['Gerçek dünyanın tüm ayrıntılarını aynen kopyalamak', 'Sonuçları sınanamaz hâle getirmek', 'Yalnızca matematik bilenlerin anlamasını sağlamak'], 'Harita gibi, iyi bir model gereksiz ayrıntıyı dışarıda bırakarak incelenen soru için önemli olan ilişkileri gösterir.'),
  ('Hiç kimsenin durumunu kötüleştirmeden en az bir kişinin durumunu iyileştirmenin mümkün olmadığı kaynak dağılımına ne ad verilir?', 'Pareto etkinliği', ['Nash dengesi', 'Gini katsayısı', 'Kapanma noktası'], 'İtalyan iktisatçı Vilfredo Pareto\'nun adını taşıyan bu ölçüt, kaynak israfının olmadığı dağılımları tanımlar.'),
  ('Pareto etkin bir dağılım için aşağıdakilerden hangisi doğrudur?', 'Gelir dağılımının adil olduğunu kendiliğinden göstermez.', ['Herkesin eşit miktarda mal sahibi olmasını gerektirir.', 'Bir kişinin her şeye sahip olduğu durum asla Pareto etkin olamaz.', 'Yalnızca komuta ekonomilerinde ortaya çıkar.'], 'Bir kişinin her şeye sahip olduğu dağılım bile Pareto etkin olabilir; çünkü başkasını iyileştirmek o kişiyi kötüleştirir. Etkinlik ile hakkaniyet ayrı ölçütlerdir.'),
  ('Elinde fazladan elma bulunan Can ile fazladan armut bulunan Deniz isteyerek takas yapıyor ve ikisi de daha mutlu oluyor. Takas öncesi dağılım için ne söylenir?', 'Pareto etkin değildir.', ['Pareto etkindir.', 'Tahsis etkinliğini tam sağlıyordur.', 'Bir negatif dışsallık örneğidir.'], 'Takasla kimsenin durumu kötüleşmeden ikisinin de durumu iyileştiyse önceki dağılımda değerlendirilmemiş bir kazanç vardı; yani Pareto etkin değildi.'),
  ('Ekonomide "etkinlik" ile "hakkaniyet" arasındaki gerilime örnek olarak aşağıdakilerden hangisi gösterilebilir?', 'Yüksek gelir vergilerinin çalışma güdüsünü azaltabilmesi', ['Arz ile talebin dengeye gelmesi', 'Bir malın fiyatının düşünce talebinin artması', 'Paranın değişim aracı olarak kullanılması'], 'Geliri yeniden dağıtmak adaleti artırabilir, ancak vergiler teşvikleri bozarak toplam üretimi azaltabilir.'),
  ('İki sektörlü basit döngüsel akım modelinde firmalardan hane halklarına doğru hangi reel akım gerçekleşir?', 'Mal ve hizmetler', ['Ücret ödemeleri', 'Tüketim harcamaları', 'Üretim faktörleri'], 'Firmalar ürettikleri mal ve hizmetleri hane halklarına sunar; buna karşılık hane halkları tüketim harcaması yapar.'),
  ('Döngüsel akım modelinde hane halklarının firmalara yaptığı tüketim harcamaları firmalar açısından neyi oluşturur?', 'Satış gelirini', ['Faktör maliyetlerini', 'Vergi yükünü', 'Tasarrufları'], 'Bir tarafın harcaması diğer tarafın gelirdir; tüketim harcamaları firmaların hasılatına dönüşür.'),
  ('Bir öğretmenin okulda çalışıp maaş alması döngüsel akım modelinde nasıl gösterilir?', 'Faktör piyasasında emek sunup ücret elde etmesi', ['Mal piyasasında mal satın alması', 'Mal piyasasında mal satması', 'Faktör piyasasında sermaye satın alması'], 'Öğretmen hane halkının bir üyesi olarak emeğini sunar; maaş, emek faktörünün getirisidir.'),
  ('Daha önce yapılmış ve hangi karar alınırsa alınsın geri alınamayacak harcamalara ne ad verilir?', 'Batık maliyet', ['Fırsat maliyeti', 'Marjinal maliyet', 'Değişken maliyet'], 'Batık maliyetler geçmişte kalmıştır; gelecekteki seçenekler arasında karar verirken dikkate alınmamalıdır.'),
  ('Mert, iade edilemeyen 300 TL\'lik bir konser biletini aldıktan sonra o akşam hastalanmış ve konsere gitmenin kendisine keyif değil sıkıntı vereceğini düşünmektedir. Rasyonel karar için hangisi doğrudur?', '300 TL karara etki etmemeli; gitmenin şimdiki yarar ve maliyetine bakmalıdır.', ['Bilete para ödediği için ne olursa olsun gitmelidir.', '300 TL\'yi kurtarmak için bileti iki katına satmaya zorlamalıdır.', 'Bilet parası fırsat maliyeti olduğu için mutlaka gitmelidir.'], 'Bilet parası hangi seçim yapılırsa yapılsın geri gelmez; bu bir batık maliyettir. Karar yalnızca gelecekteki yarar ve maliyetlere göre verilmelidir.'),
  ('İnsanların sırf daha önce çok emek ve para harcadıkları için başarısız bir projeye devam etmelerine ne ad verilir?', 'Batık maliyet yanılgısı', ['Ölçek ekonomisi', 'Fiyat farklılaştırması', 'Karşılaştırmalı üstünlük'], 'Geçmiş harcamaları kurtarma isteği, rasyonel olmayan biçimde zarar eden faaliyetlerin sürdürülmesine yol açar.'),
  ('Ekonomide "rasyonel karar verici" varsayımı en doğru biçimde nasıl açıklanır?', 'Kişinin, eldeki bilgiyle amacına en iyi hizmet eden seçeneği seçmeye çalışması', ['Kişinin her zaman en ucuz malı satın alması', 'Kişinin hiçbir zaman hata yapmaması', 'Kişinin yalnızca parasal kazanca önem vermesi'], 'Rasyonellik, kişinin tercihleri doğrultusunda marjinal yarar ve maliyetleri tartarak tutarlı seçim yapmasıdır; başkalarını önemsemek de rasyonel olabilir.'),
  ('Bir kişiyi belli bir biçimde davranmaya yönelten ödül ya da cezaya ekonomide ne ad verilir?', 'Teşvik', ['Kıtlık', 'Dışsallık', 'Rant'], 'İnsanlar teşviklere tepki verir; fiyatlar, vergiler ve sübvansiyonlar davranışları değiştiren teşviklerdir.'),
  ('Bir belediye plastik poşetlere ücret getirdikten sonra market müşterilerinin bez çanta kullanımı belirgin biçimde artmıştır. Bu gözlem hangi ilkeyi destekler?', 'İnsanlar teşviklere tepki verir.', ['İnsanlar fiyatlara hiç duyarlı değildir.', 'Talep kanunu poşetler için geçerli değildir.', 'Bez çanta düşük bir maldır.'], 'Küçük bir ücret bile poşet kullanmanın maliyetini artırmış ve tüketicileri alternatife yöneltmiştir.'),
  ('Bir mağazanın önce çok pahalı bir ürünü göstererek ardından orta fiyatlı ürünü daha makul göstermesi hangi davranışsal etkiye dayanır?', 'Çapalama etkisi', ['Gelir etkisi', 'İkame etkisi', 'Veblen etkisi'], 'İlk görülen sayı bir çapa işlevi görür ve sonraki değerlendirmeleri etkiler; orta fiyat bu yüzden ucuz algılanır.'),
  ('Herbert Simon\'ın ileri sürdüğü, insanların bilgi ve zaman kısıtları nedeniyle en iyiyi değil yeterince iyi olanı seçtiğini anlatan kavram hangisidir?', 'Sınırlı rasyonellik', ['Mükemmel rekabet', 'Tam bilgi', 'Ölçek ekonomisi'], 'Simon, karar vericilerin sınırlı bilgi ve işlem kapasitesiyle "tatmin edici" seçimler yaptığını savunmuştur.'),
  ('GSYH hesaplanırken ara malların ayrıca sayılmamasının nedeni nedir?', 'Değerleri nihai malın fiyatına zaten dâhil olduğundan çift sayım olmasını önlemek', ['Ara malların hiçbir ekonomik değeri olmadığından', 'Ara malların yalnızca ithal edilmesinden', 'Devletin ara mallardan vergi almamasından'], 'Ekmek fiyatının içinde un ve buğdayın değeri de vardır; un ve buğday ayrıca eklenirse üretim fazla gösterilir.'),
  ('Bir çiftçi buğdayını 200 TL\'ye değirmene satıyor, değirmen unu 350 TL\'ye fırına satıyor, fırın da ekmekleri 600 TL\'ye tüketicilere satıyor. Fırının yarattığı katma değer kaç TL\'dir?', '250 TL', ['600 TL', '350 TL', '1.150 TL'], 'Katma değer = satış değeri − satın alınan ara malların değeri = 600 − 350 = 250 TL\'dir. Tüm aşamaların katma değerleri toplamı nihai mal değerine (600 TL) eşittir.'),
  ('Aşağıdakilerden hangisi bir yılın GSYH\'sine dâhil edilmez?', 'Geçen yıl üretilmiş bir evin bu yıl ikinci el satışı', ['Bu yıl üretilip satılan yeni bir otomobil', 'Bu yıl verilen kuaförlük hizmeti', 'Bu yıl inşa edilen yeni bir fabrika'], 'GSYH o dönemdeki üretimi ölçer. İkinci el satışlar yeni üretim değildir; yalnızca var olan bir malın el değiştirmesidir.'),
  ('Gayrisafi milli hasıla (GSMH) GSYH\'den hangi ölçüt bakımından ayrılır?', 'Coğrafi sınırlar yerine vatandaşların ürettiği değeri esas alır.', ['Yalnızca tarımsal üretimi ölçer.', 'Ara malları da hesaba katar.', 'Yalnızca devletin üretimini kapsar.'], 'GSYH ülke sınırları içindeki üretimi, GSMH ise yurt içinde ya da dışında olsun ülke vatandaşlarına ait faktörlerin üretimini ölçer.'),
  ('Bankacılık, eğitim, sağlık ve turizm hangi sektör içinde değerlendirilir?', 'Hizmetler sektörü', ['Sanayi sektörü', 'Tarım sektörü', 'Madencilik sektörü'], 'Somut bir mal üretmeyen, tüketiciye ya da firmalara hizmet sunan faaliyetler üçüncül yani hizmetler sektörüne girer.'),
  ('Ülkeler ekonomik olarak geliştikçe istihdamın sektörler arasındaki dağılımında genellikle hangi eğilim gözlenir?', 'Tarımın payı azalır, hizmetlerin payı artar.', ['Tarımın payı sürekli artar.', 'Hizmetlerin payı sıfıra iner.', 'Sanayinin payı her zaman sürekli artmaya devam eder.'], 'Tarımda verimlilik arttıkça daha az işçiyle daha çok üretilir; işgücü önce sanayiye, ardından ağırlıklı olarak hizmetlere kayar.'),
  ('Emek verimliliği en yaygın biçimde nasıl ölçülür?', 'Çalışan başına ya da çalışılan saat başına üretim', ['Toplam ücretlerin nüfusa oranı', 'İşsizlerin çalışanlara oranı', 'İhracatın ithalata oranı'], 'Emek verimliliği, birim emek girdisi başına elde edilen çıktıdır; yaşam standartlarının uzun dönemde temel belirleyicisidir.'),
  ('Uzun dönemde bir ülkenin yaşam standardını en çok belirleyen etken hangisidir?', 'Mal ve hizmet üretmedeki verimliliği', ['Bastığı para miktarı', 'Nüfusunun büyüklüğü', 'Yüzölçümü'], 'Bir ülkenin vatandaşları ancak ürettikleri kadarını tüketebilir; kişi başına üretimi artıran verimlilik yaşam standardının ana kaynağıdır.'),
  ('Bir fabrikada 50 işçi ayda 10.000 ürün üretirken yeni makinelerle 50 işçi ayda 12.500 ürün üretmeye başlamıştır. İşçi başına verimlilik yüzde kaç artmıştır?', '%25', ['%20', '%12,5', '%50'], 'İşçi başına üretim 200\'den 250\'ye çıkmıştır; artış 50 / 200 = %25\'tir.'),
  ('Bir fabrika bir makineyle saatte ya 30 masa ya da 60 sandalye üretebilmektedir. Bu makinede 1 masa üretmenin fırsat maliyeti nedir?', '2 sandalye', ['0,5 sandalye', '30 sandalye', '60 sandalye'], 'Makine 30 masa yerine 60 sandalye üretebiliyor; 1 masa için 60 / 30 = 2 sandalyeden vazgeçilir.'),
  ('Bir kişinin saatlik kazancı yükseldikçe yemeği evde kendisi pişirmenin fırsat maliyeti nasıl değişir?', 'Artar.', ['Azalır.', 'Değişmez.', 'Sıfıra iner.'], 'Yemek pişirmeye ayrılan bir saatte vazgeçilen kazanç büyüdüğü için bu etkinliğin fırsat maliyeti yükselir; yüksek gelirliler bu yüzden hazır yemeğe daha çok yönelir.'),
  ('Bir ülkede yalnızca tarım teknolojisinin gelişmesi, sanayi ve tarım mallarını gösteren üretim imkânları eğrisini nasıl etkiler?', 'Eğri tarım ekseni yönünde dışa doğru döner.', ['Eğri her iki yönde eşit miktarda paralel kayar.', 'Eğri sanayi ekseni yönünde içe kayar.', 'Eğrinin konumu değişmez.'], 'Teknoloji yalnızca tarımda geliştiğinden azami tarım üretimi artar; azami sanayi üretimi aynı kalır ve eğri tarım ekseninde genişler.'),
  ('Merkezî planlama ekonomilerinde fiyatların devletçe belirlenmesi sık karşılaşılan hangi soruna yol açmıştır?', 'Bazı mallarda kıtlık ve kuyruklar oluşması', ['Tüm mallarda sürekli arz fazlası olması', 'Firmaların aşırı kâr elde etmesi', 'Reklam harcamalarının aşırı artması'], 'Fiyatlar kıtlığı yansıtmadığından talep edilen miktar çoğu malda üretimi aşmış ve kıtlık yaşanmıştır.'),
  ('Bir bilet satıcısı fiyatı 100 TL iken günde 300, fiyatı 80 TL iken günde 380 bilet satmaktadır. Talep doğrusal ise fiyat 60 TL olduğunda kaç bilet satılır?', '460', ['420', '400', '500'], 'Fiyattaki her 20 TL\'lik düşüş satışları 80 bilet artırıyor; 60 TL\'de 380 + 80 = 460 bilet satılır.'),
  ('Bir malın talebini belirleyen etkenlerden biri olan "tüketicilerin geliri" düştüğünde normal bir malın talep eğrisine ne olur?', 'Sola kayar.', ['Sağa kayar.', 'Eğri üzerinde aşağı hareket olur.', 'Yatay hâle gelir.'], 'Normal mallarda gelir ile talep aynı yönlüdür; gelir azalınca her fiyatta daha az talep edilir.'),
  ('Bir malın arz tablosuna göre fiyat 10 TL iken 50, 14 TL iken 70 birim arz edilmektedir. Arz doğrusal ise fiyat 18 TL olduğunda kaç birim arz edilir?', '90', ['80', '100', '110'], 'Fiyattaki her 4 TL\'lik artış arzı 20 birim artırıyor; 18 TL\'de 70 + 20 = 90 birim arz edilir.'),
  ('Devletin bir malın üretiminde kullanılan girdiye yeni bir vergi koyması o malın arz eğrisini nasıl etkiler?', 'Sola kaydırır.', ['Sağa kaydırır.', 'Etkilemez, yalnızca talep kayar.', 'Eğrinin eğimini negatif yapar.'], 'Girdi vergisi üretim maliyetini artırır ve her fiyatta daha az üretimi kârlı kılar.'),
  ('Talebin Qd = 50 − P, arzın Qs = P − 10 olduğu bir piyasada denge fiyatı kaç TL\'dir?', '30 TL', ['20 TL', '40 TL', '25 TL'], '50 − P = P − 10 ise 2P = 60 ve P = 30 TL\'dir; denge miktarı 20 birimdir.'),
  ('Fiyat esnekliği 0,5 olan bir malın fiyatı %10 artarsa talep edilen miktar yaklaşık yüzde kaç azalır?', '%5', ['%20', '%10', '%0,5'], 'Miktardaki değişme = esneklik × fiyattaki değişme = 0,5 × %10 = %5.'),
  ('Bir müzenin bilet fiyatını %20 artırdığında ziyaretçi sayısı %30 azalmıştır. Müzenin bilet geliri için ne söylenebilir?', 'Düşmüştür.', ['Artmıştır.', 'Değişmemiştir.', 'İki katına çıkmıştır.'], 'Miktardaki düşüş fiyattaki artıştan büyük olduğundan talep esnektir; gelir 1,2 × 0,7 = 0,84 katına düşer.'),
  ('Bir malın gelir esnekliği 2 ise gelir %5 azaldığında talebi nasıl değişir?', '%10 azalır.', ['%10 artar.', '%2,5 azalır.', '%5 artar.'], 'Talepteki değişme = 2 × (−%5) = −%10\'dur; lüks mallar gelir düşüşlerinden güçlü etkilenir.'),
  ('Arz eğrisi tamamen yatay olan bir malın arz esnekliği için hangisi doğrudur?', 'Sonsuzdur.', ['Sıfırdır.', 'Birdir.', 'Negatiftir.'], 'Yatay arz eğrisinde üreticiler belirli fiyatta her miktarı sunmaya hazırdır; fiyatın azıcık düşmesi arzı sıfırlar.'),
  ('Bir sahafta üç alıcı aynı kitap için sırasıyla en çok 90, 70 ve 50 TL ödemeye razıdır. Kitabın fiyatı 60 TL ise kitabı alanların toplam tüketici rantı kaç TL\'dir?', '40 TL', ['30 TL', '50 TL', '90 TL'], '60 TL\'de yalnızca ilk iki alıcı satın alır. Rantları 30 ve 10 TL olup toplam 40 TL\'dir; üçüncü alıcı satın almaz.'),
  ('Bir malın piyasa fiyatı düştüğünde üretici rantına ne olur?', 'Azalır.', ['Artar.', 'Değişmez.', 'Tüketici rantına eşitlenir.'], 'Satıcıların aldığı fiyat ile kabul edecekleri en düşük fiyat arasındaki fark daralır; bazı satıcılar da piyasadan çekilir.'),
  ('Bağlayıcı bir tavan fiyat uygulanan bir malda satıcıların yasal fiyatı korurken paket boyutunu küçültmesi ya da kaliteyi düşürmesi nasıl açıklanır?', 'Fiyat dışı yollarla kıtlığa uyum sağlanması', ['Talebin tamamen ortadan kalkması', 'Arz fazlasının stoklanması', 'Tüketici rantının kendiliğinden artması'], 'Fiyat yükseltilemeyince satıcılar ürünün niteliğini değiştirerek etkin fiyatı artırır; bu, tavan fiyatın sık görülen yan etkilerindendir.'),
  ('Bir tarım ürününde talep Qd = 120 − 2P ve arz Qs = 3P − 30\'dur. Üreticileri korumak isteyen hükümet fiyatın 40 TL\'nin altına inmesini yasaklarsa piyasada kaç birim ürün alıcı bulamaz?', '50', ['40', '90', '10'], 'Denge fiyatı 120 − 2P = 3P − 30 eşitliğinden 30 TL\'dir. 40 TL\'de Qd = 40, Qs = 90 olur; arz fazlası 50 birimdir.'),
  ('Arz eğrisi tamamen yatay (tam esnek) olan bir piyasada birim başına konan verginin yükünü kim taşır?', 'Tamamen alıcılar', ['Tamamen satıcılar', 'Alıcılar ve satıcılar yarı yarıya', 'Hiç kimse'], 'Satıcılar fiyattaki en küçük düşüşte arzı keser; bu yüzden fiyat vergi kadar yükselir ve yük alıcılara geçer.'),
  ('Bir tüketicinin elma tüketiminde marjinal faydalar sırasıyla 12, 9, 6 ve 3\'tür. Dört elmanın toplam faydası kaçtır?', '30', ['3', '12', '27'], 'Toplam fayda, marjinal faydaların toplamıdır: 12 + 9 + 6 + 3 = 30.'),
  ('Azalan marjinal fayda ilkesi talep eğrisinin negatif eğimli olmasını nasıl destekler?', 'Tüketici ek birimler için daha az ödemeye razıdır.', ['Tüketici her birim için aynı fiyatı ödemeye razıdır.', 'Üretici fiyatı artırdıkça daha çok üretir.', 'Tüketicinin geliri her birimde artar.'], 'Her ek birim daha az fayda sağladığından tüketici onu ancak daha düşük fiyattan almaya razı olur.'),
  ('Geliri 240 TL olan bir tüketici için X malının fiyatı 12 TL, Y malının fiyatı 8 TL\'dir. Tüketici 10 birim X alırsa en çok kaç birim Y alabilir?', '15', ['30', '20', '12'], '10 birim X için 120 TL harcanır; kalan 120 TL ile 120 / 8 = 15 birim Y alınabilir.'),
  ('Bütçe doğrusunun eğimi neyi gösterir?', 'İki malın göreli fiyatını', ['Tüketicinin toplam faydasını', 'Tüketicinin tasarrufunu', 'Malların kalitesini'], 'Eğim, piyasada bir malın kaç birim diğer mal karşılığında elde edilebileceğini yani fiyat oranını gösterir.'),
  ('Emeğin marjinal ürünü azalmaya başladığında toplam ürün için ne söylenebilir?', 'Artmaya devam eder ama daha yavaş artar.', ['Hemen azalmaya başlar.', 'Sıfıra iner.', 'Daha hızlı artmaya başlar.'], 'Marjinal ürün azalsa bile pozitif olduğu sürece toplam ürün artar; yalnızca artış hızı yavaşlar.'),
  ('Bir kafede tek bir espresso makinesi varken çalışan sayısının ikiden beşe çıkarılmasıyla müşteri başına hizmet süresinin uzaması neyi gösterir?', 'Sabit girdiye fazla değişken girdi eklendiğini', ['Ölçeğe göre artan getiri olduğunu', 'Talebin azaldığını', 'Makinenin değişken girdi olduğunu'], 'Makine sabitken çalışan arttıkça her çalışanın katkısı azalır, hatta birbirlerini engellemeye başlarlar; bu azalan verimlerin belirtisidir.'),
  ('Bir firmanın sabit maliyeti 6.000 TL\'dir. Firma 300 birim üretirse ortalama sabit maliyet kaç TL olur?', '20 TL', ['300 TL', '1.800 TL', '50 TL'], 'Ortalama sabit maliyet = 6.000 / 300 = 20 TL\'dir.'),
  ('Bir fabrikada 1.000 birim üretimin toplam maliyeti 50.000 TL, 2.000 birim üretiminki 80.000 TL\'dir. Ortalama maliyet nasıl değişmiştir?', '50 TL\'den 40 TL\'ye düşmüştür.', ['50 TL\'den 80 TL\'ye çıkmıştır.', 'Değişmemiştir.', '40 TL\'den 50 TL\'ye çıkmıştır.'], 'Ortalama maliyet 50.000 / 1.000 = 50 TL\'den 80.000 / 2.000 = 40 TL\'ye düşmüştür; bu ölçek ekonomisine işaret eder.'),
  ('Tam rekabetteki bir firma için kâr maksimizasyonu koşulu hangi eşitliğe dönüşür?', 'Fiyat = marjinal maliyet', ['Fiyat = ortalama sabit maliyet', 'Fiyat = toplam maliyet', 'Marjinal maliyet = sıfır'], 'Tam rekabette marjinal hasılat fiyata eşit olduğundan MR = MC koşulu P = MC olur.'),
  ('Tam rekabet piyasasında firmaların reklam yapmaya genellikle gerek duymamasının nedeni nedir?', 'Ürünler homojen olduğu için', ['Devletin reklamı yasaklaması', 'Firmaların çok büyük olması', 'Tüketicilerin hiç bilgi sahibi olmaması'], 'Tüm firmalar aynı ürünü sattığından bir firmanın reklamı yalnızca piyasanın tamamına yarar, o firmaya özel kazanç sağlamaz.'),
  ('Tekelci bir firma talebin inelastik olduğu bölgede üretim yapmaz. Bunun nedeni nedir?', 'Bu bölgede marjinal hasılat negatiftir.', ['Bu bölgede marjinal maliyet sıfırdır.', 'Devlet bunu yasaklamıştır.', 'Talep eğrisi bu bölgede yataydır.'], 'İnelastik bölgede fiyat artırmak hasılatı artırır, maliyeti de düşürür; bu yüzden kâr maksimize eden tekel esnek bölgeye geçer.'),
  ('Doğal tekellerde devletin sıkça başvurduğu politika aracı hangisidir?', 'Fiyatların düzenleyici kurumlarca denetlenmesi', ['Firmaların sayısının yasayla artırılması', 'Tüm fiyatların sıfırlanması', 'Malın üretiminin yasaklanması'], 'Tek firmayla üretim maliyet açısından etkin olduğundan devlet rekabet yaratmak yerine fiyat ve hizmet kalitesini düzenler.'),
  ('Bir elektrik dağıtım şirketinin gece saatlerinde kullanılan elektriği gündüzden daha ucuza satması hangi uygulamaya örnek gösterilebilir?', 'Zamana dayalı fiyatlandırma', ['Kartel anlaşması', 'Tavan fiyat', 'Ters seçim'], 'Talebin düşük olduğu saatlerde fiyatı düşürmek, tüketimi farklı zamanlara yaymayı amaçlayan bir fiyatlandırma biçimidir.'),
  ('Monopolcü rekabetteki bir firmanın talep eğrisi tam rekabetteki firmanınkinden nasıl ayrılır?', 'Negatif eğimlidir.', ['Tamamen yataydır.', 'Tamamen dikeydir.', 'Pozitif eğimlidir.'], 'Ürün farklılaştırması firmaya bir miktar müşteri bağlılığı sağlar; fiyatı biraz artırınca müşterilerin tamamını değil bir kısmını kaybeder.'),
  ('Petrol ihraç eden ülkelerin üretim kotalarını birlikte belirlemesiyle bilinen örgüt hangisidir?', 'OPEC', ['NATO', 'UNESCO', 'FIFA'], '1960\'ta kurulan Petrol İhraç Eden Ülkeler Örgütü, üyelerinin üretim politikalarını koordine eden ve sıkça kartel örneği olarak verilen bir yapıdır.'),
  ('Bir işçinin işverene katkısını gösteren "emeğin marjinal ürün hasılatı" nasıl hesaplanır?', 'Marjinal ürün ile ürünün marjinal hasılatının çarpımıyla', ['Ücretin işçi sayısına bölünmesiyle', 'Toplam maliyetin toplam ürüne bölünmesiyle', 'Sabit maliyetin ücretle toplanmasıyla'], 'Ek işçinin ürettiği ek birimler, her birimin getirdiği ek hasılatla çarpılarak işçinin firmaya kazandırdığı gelir bulunur.'),
  ('Henry Ford\'un otomobil üretiminde hareketli montaj bandını kullanmaya başlaması hangi ilkenin uygulamasıdır?', 'İşbölümü ve uzmanlaşma', ['Tam rekabet', 'Fiyat tavanı', 'Ters seçim'], 'Montaj bandında her işçi tek bir işlemi tekrarlar; bu, üretim süresini kısaltıp maliyetleri düşürmüştür.'),
  ('Negatif üretim dışsallığı olan bir malda toplumsal marjinal maliyet ile özel marjinal maliyet arasındaki ilişki nedir?', 'Toplumsal maliyet özel maliyetten büyüktür.', ['Toplumsal maliyet özel maliyetten küçüktür.', 'İkisi her zaman eşittir.', 'Özel maliyet sıfırdır.'], 'Toplumsal maliyet, özel maliyete üçüncü kişilere yüklenen dışsal zararın eklenmesiyle bulunur.'),
  ('Kamusal malların genellikle devlet tarafından vergilerle finanse edilmesinin nedeni nedir?', 'Piyasa bu malları yeterince sunamaz.', ['Bu mallar hiç maliyet gerektirmez.', 'Bu mallar yalnızca zenginlere yöneliktir.', 'Bu mallar yasal olarak satılamaz.'], 'Dışlanamazlık nedeniyle insanlar gönüllü ödeme yapmaz; özel firmalar maliyetini karşılayamadığından devlet zorunlu vergilerle finanse eder.'),
  ('Tam rekabet piyasasında uzun dönem dengesinin etkin sayılmasının temel nedeni hangisidir?', 'Fiyat hem marjinal hem en düşük ortalama maliyete eşittir.', ['Firmalar en yüksek ekonomik kârı elde eder.', 'Fiyat marjinal maliyetin iki katıdır.', 'Tüketici rantı sıfırdır.'], 'P = MC tahsis etkinliğini, P = min AC üretim etkinliğini sağlar.'),
  ('Döngüsel akım modeline devlet eklendiğinde hane halklarından devlete hangi akım yönelir?', 'Vergiler', ['Sübvansiyonlar', 'Kamu hizmetleri', 'Transfer ödemeleri'], 'Hane halkları ve firmalar devlete vergi öder; devlet de karşılığında kamu hizmetleri ve transferler sağlar.'),
  ('Davranışsal ekonomi geleneksel ekonomi anlayışından hangi yönüyle ayrılır?', 'İnsanların sistematik karar hataları yapabileceğini kabul eder.', ['İnsanların her zaman tam bilgiyle karar verdiğini varsayar.', 'Fiyatların davranışı hiç etkilemediğini savunur.', 'Yalnızca devletin kararlarını inceler.'], 'Davranışsal ekonomi psikolojiden yararlanarak gerçek insanların sınırlı dikkat, alışkanlık ve önyargılarla karar verdiğini inceler.'),
  ('Bir ülkede bir yılda yalnızca 1.000 TL\'lik tüketim, 300 TL\'lik yatırım, 400 TL\'lik kamu harcaması yapılmış; ihracat 200 TL ve ithalat 250 TL olmuştur. Harcama yöntemiyle GSYH kaç TL\'dir?', '1.650 TL', ['1.700 TL', '2.150 TL', '1.900 TL'], 'GSYH = C + I + G + (X − M) = 1.000 + 300 + 400 + (200 − 250) = 1.650 TL\'dir.'),
  ('Fiyatlar artmadan yalnızca üretim miktarındaki değişmeyi görebilmek için hangi GSYH ölçüsü kullanılır?', 'Reel GSYH', ['Nominal GSYH', 'Kişi başına vergi', 'Cari GSYH'], 'Reel GSYH, üretimi sabit bir baz yılın fiyatlarıyla ölçerek fiyat değişmelerinin etkisini dışarıda bırakır.'),
  ('Bir ülkede bir yılda bilgi ve iletişim teknolojileri, finans ve eğitim gibi alanların GSYH içindeki payının hızla artması hangi sektörün büyüdüğünü gösterir?', 'Hizmetler sektörünün', ['Tarım sektörünün', 'Madencilik sektörünün', 'Birincil sektörün'], 'Bu alanların tümü somut mal üretmeyen, bilgi ve hizmet sunan faaliyetlerdir.'),
  ('Bir ülkede yeni yolların, limanların ve elektrik şebekelerinin yapılması üretim kapasitesine nasıl katkı sağlar?', 'Altyapı sermayesi olarak verimliliği artırır.', ['Doğal kaynakları azaltarak üretimi düşürür.', 'Talep kanununu ortadan kaldırır.', 'Yalnızca tüketim malı olarak sayılır ve üretimi etkilemez.'], 'Altyapı, firmaların mal taşıma ve üretim maliyetlerini düşürerek ekonominin genel verimliliğini yükseltir.'),
  ('"Homo economicus" kavramı ekonomik modellerde nasıl bir insanı tanımlar?', 'Kendi çıkarını rasyonel biçimde en yükseğe çıkarmaya çalışan birey', ['Yalnızca toplum yararını düşünen birey', 'Kararlarını tamamen rastgele veren birey', 'Hiç tüketim yapmayan birey'], 'Ekonomik insan varsayımı, bireylerin tutarlı tercihlere sahip ve faydalarını en çoklamaya çalışan karar vericiler olduğunu kabul eder.'),
  ('Bir firmanın uzun dönem ortalama maliyet eğrisi nasıl oluşur?', 'Farklı tesis büyüklüklerine ait kısa dönem eğrilerinin en düşük kısımlarından', ['Tek bir kısa dönem eğrisinin aynen uzatılmasından', 'Talep eğrisinin tersinin alınmasından', 'Sabit maliyet eğrisinin iki katına çıkarılmasından'], 'Uzun dönemde firma her üretim düzeyi için en uygun tesisi seçebilir; uzun dönem eğrisi kısa dönem eğrilerinin zarfıdır.'),
  ('Bir ev sahibinin kiracıdan depozito alması, kiracının sözleşme imzalandıktan sonra evi özensiz kullanma olasılığına karşı alınmış bir önlemdir. Bu önlem hangi sorunu hedefler?', 'Ahlaki tehlike', ['Ters seçim', 'Bedavacılık', 'Ölçek eksi ekonomisi'], 'Sözleşme sonrasında kiracının davranışı tam gözlenemez; depozito, zararın bir kısmını kiracıya yükleyerek özenli davranma güdüsünü korur.'),
  ('Karma ekonomide devletin sağlık ve eğitim gibi hizmetleri sunmasının ekonomik gerekçelerinden biri hangisidir?', 'Bu hizmetlerin pozitif dışsallıklar yaratması', ['Piyasanın bu hizmetleri aşırı üretmesi', 'Bu hizmetlerin hiçbir maliyeti olmaması', 'Bu hizmetlere hiç talep bulunmaması'], 'Eğitimli ve sağlıklı bireyler topluma da fayda sağlar; piyasa bu yararı fiyatlamadığından hizmetleri eksik sunabilir.'),
  ('Bir ekonomistin "Bu vergi tüketimi yüzde 5 azaltır, ancak bence uygulanmamalıdır." sözünde hangi ifade türleri bulunur?', 'Önce pozitif, sonra normatif ifade', ['Önce normatif, sonra pozitif ifade', 'Yalnızca pozitif ifadeler', 'Yalnızca normatif ifadeler'], 'Etkiye ilişkin ilk kısım sınanabilir bir tahmindir; ikinci kısım ise kişisel değer yargısıdır.'),
  ('Gelirler %20 artarken bir ailenin ekmek talebi %4 artmıştır. Ekmeğin gelir esnekliği ve sınıfı hangisidir?', '0,2; zorunlu mal', ['5; lüks mal', '−0,2; düşük mal', '0,8; lüks mal'], 'Gelir esnekliği = %4 / %20 = 0,2\'dir. 0 ile 1 arasında olduğu için ekmek bu aile için zorunlu bir normal maldır.'),
  ('Kolay bozulan çilek gibi ürünlerin hasat zamanında arz esnekliği neden düşüktür?', 'Depolanamadıkları için fiyat düşse de satılmak zorundadırlar.', ['Üretimleri çok hızlı artırılabildiği için', 'Talepleri tam esnek olduğu için', 'Devlet bu ürünlere taban fiyat koyduğu için'], 'Stoklanamayan ürünlerde üretici, fiyat ne olursa olsun elindeki ürünü satmak zorunda kalır; arz miktarı fiyata az tepki verir.'),
  ('Bir tüketici, fiyatı sıfır olan bir maldan ne kadar tüketir?', 'Marjinal faydası sıfır olana kadar', ['Toplam faydası sıfır olana kadar', 'Yalnızca bir birim', 'Marjinal faydası en yüksek olana kadar'], 'Bedava bir malı tüketici, ek birimin artık hiçbir fayda sağlamadığı noktaya kadar tüketir.'),
  ('Monopolcü rekabette tüketicilerin elde ettiği avantaj nedir?', 'Ürün çeşitliliğinin fazla olması', ['Tüm ürünlerin tamamen aynı olması', 'Fiyatların her zaman marjinal maliyete eşit olması', 'Firmaların hiç reklam yapmaması'], 'Farklılaştırılmış ürünler tüketicilere farklı zevklere uygun pek çok seçenek sunar; bunun bedeli atıl kapasitedir.'),
  ('Bir internet sitesinde satıcıların geçmiş müşteri puanlarının gösterilmesi hangi soruna çözüm sağlar?', 'Asimetrik bilgi', ['Kamusal mal sunumu', 'Negatif dışsallık', 'Azalan verimler'], 'Puanlar alıcıların satıcı kalitesi hakkındaki bilgi eksikliğini azaltır ve güven oluşturur.'),
  ('Bir firmanın kârını en yükseğe çıkardığı üretim düzeyinde kâr negatif çıkıyorsa bu düzey için ne söylenir?', 'Zararın en aza indirildiği düzeydir.', ['Kârın sıfır olduğu düzeydir.', 'Firmanın tekel olduğunu gösterir.', 'Muhasebe hatası olduğunu gösterir.'], 'MR = MC kuralı her durumda kâr ile zarar arasındaki farkı en iyi yapar; kâr mümkün değilse zararı en aza indirir.'),
];
